/* DAWAH X — ahmad, অধ্যায় 24 · খণ্ড 24 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][24]=[[4601,4601,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاذٌ ‏ ‏حَدَّثَنَا ‏ ‏عِمْرَانُ بْنُ حُدَيْرٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ عُطَارِدٍ أَبِي الْبَزَرِى ‏ ‏قَالَ قَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏كُنَّا نَشْرَبُ وَنَحْنُ قِيَامٌ وَنَأْكُلُ وَنَحْنُ ‏ ‏نَسْعَى عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[4602,4602,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاذٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عَوْنٍ ‏ ‏عَنْ ‏ ‏مُسْلِمٍ ‏ ‏مَوْلًى ‏ ‏لِعَبْدِ الْقَيْسِ ‏ ‏قَالَ ‏ ‏مُعَاذٌ ‏ ‏كَانَ ‏ ‏شُعْبَةُ ‏ ‏يَقُولُ ‏ ‏الْقُرِّيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَجُلٌ ‏ ‏لِابْنِ عُمَرَ ‏ ‏أَرَأَيْتَ ‏ ‏الْوِتْرَ ‏ ‏أَسُنَّةٌ هُوَ قَالَ مَا سُنَّةٌ ‏ ‏أَوْتَرَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَوْتَرَ الْمُسْلِمُونَ قَالَ لَا أَسُنَّةٌ هُوَ قَالَ ‏ ‏مَهْ ‏ ‏أَوَتَعْقِلُ ‏ ‏أَوْتَرَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَوْتَرَ ‏ ‏الْمُسْلِمُونَ ‏","","",""],[4603,4603,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاذٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عَوْنٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏نَادَى رَجُلٌ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَاذَا يَلْبَسُ ‏ ‏الْمُحْرِمُ ‏ ‏مِنْ الثِّيَابِ فَقَالَ ‏ ‏لَا تَلْبَسُوا الْقَمِيصَ وَلَا الْعِمَامَةَ وَلَا ‏ ‏الْبَرَانِسَ ‏ ‏وَلَا السَّرَاوِيلَاتِ وَلَا الْخِفَافَ إِلَّا أَنْ لَا تَكُونَ نِعَالٌ فَإِنْ لَمْ تَكُنْ نِعَالٌ فَخُفَّيْنِ دُونَ الْكَعْبَيْنِ وَلَا ثَوْبًا ‏ ‏مَسَّهُ ‏ ‏وَرْسٌ ‏ ‏قَالَ ‏ ‏ابْنُ عَوْنٍ ‏ ‏إِمَّا قَالَ مَصْبُوغٌ وَإِمَّا قَالَ ‏ ‏مَسَّهُ ‏ ‏وَرْسٌ ‏ ‏وَزَعْفَرَانٌ ‏ ‏قَالَ ‏ ‏ابْنُ عَوْنٍ ‏ ‏وَفِي كِتَابِ ‏ ‏نَافِعٍ ‏ ‏مَسَّهُ ‏","","",""],[4604,4604,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏قَالَ وَذَكَرْتُ ‏ ‏لِابْنِ شِهَابٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سَالِمٌ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏قَدْ كَانَ يَصْنَعُ ذَاكَ ‏ ‏ثُمَّ حَدَّثَتْهُ ‏ ‏صَفِيَّةُ بِنْتُ أَبِي عُبَيْدٍ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏حَدَّثَتْهَا ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُرَخِّصُ لِلنِّسَاءِ فِي الْخُفَّيْنِ ‏","","",""],[4605,4605,"","","‏ ‏حَدَّثَنِي ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ يَعْنِي التَّيْمِيَّ ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏أَنَهَى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏نَبِيذِ ‏ ‏الْجَرِّ ‏ ‏قَالَ نَعَمْ ‏ ‏قَالَ ‏ ‏وَقَالَ ‏ ‏طَاوُسٌ ‏ ‏وَاللَّهِ إِنِّي سَمِعْتُهُ مِنْهُ ‏","","",""],[4606,4606,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏صَلَاةٌ فِي ‏ ‏مَسْجِدِي ‏ ‏هَذَا أَفْضَلُ مِنْ أَلْفِ صَلَاةٍ فِيمَا سِوَاهُ مِنْ الْمَسَاجِدِ إِلَّا ‏ ‏الْمَسْجِدَ الْحَرَامَ ‏ ‏فَهُوَ أَفْضَلُ ‏","","",""],[4607,4607,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا جَمَعَ اللَّهُ الْأَوَّلِينَ وَالْآخِرِينَ يَوْمَ الْقِيَامَةِ رُفِعَ لِكُلِّ ‏ ‏غَادِرٍ ‏ ‏لِوَاءٌ ‏ ‏فَقِيلَ هَذِهِ ‏ ‏غَدْرَةُ ‏ ‏فُلَانِ بْنِ فُلَانٍ ‏","","",""],[4608,4608,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏لَا ‏ ‏يَتَحَيَّنَنَّ ‏ ‏أَحَدُكُمْ طُلُوعَ الشَّمْسِ وَلَا غُرُوبَهَا فَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَنْهَى عَنْ ذَلِكَ ‏","","",""],[4609,4609,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَى ‏ ‏نُخَامَةً ‏ ‏فِي قِبْلَةِ الْمَسْجِدِ ‏ ‏فَحَتَّهَا ‏ ‏ثُمَّ أَقْبَلَ عَلَى النَّاسِ فَقَالَ ‏ ‏إِذَا كَانَ أَحَدُكُمْ فِي الصَّلَاةِ فَلَا ‏ ‏يَتَنَخَّمْ ‏ ‏قِبَلَ وَجْهِهِ فَإِنَّ اللَّهَ تَعَالَى قِبَلَ وَجْهِ أَحَدِكُمْ إِذَا كَانَ فِي الصَّلَاةِ ‏","","",""],[4610,4610,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا أَدْخَلَ رِجْلَهُ فِي ‏ ‏الْغَرْزِ ‏ ‏وَاسْتَوَتْ ‏ ‏بِهِ نَاقَتُهُ قَائِمَةً ‏ ‏أَهَلَّ ‏ ‏مِنْ مَسْجِدِ ‏ ‏ذِي الْحُلَيْفَةِ ‏","","",""],[4611,4611,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَخْرُجُ ‏ ‏مِنْ طَرِيقِ الشَّجَرَةِ وَكَانَ يَدْخُلُ ‏ ‏مَكَّةَ ‏ ‏مِنْ ‏ ‏الثَّنِيَّةِ الْعُلْيَا ‏ ‏وَيَخْرُجُ مِنْ ‏ ‏الثَّنِيَّةِ السُّفْلَى ‏","","",""],[4612,4612,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا طَافَ ‏ ‏بِالْبَيْتِ ‏ ‏الطَّوَافَ الْأَوَّلَ ‏ ‏خَبَّ ‏ ‏ثَلَاثَةً وَمَشَى أَرْبَعَةً ‏","","",""],[4613,4613,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّمَا ‏ ‏مَثَلُ الْقُرْآنِ مَثَلُ الْإِبِلِ ‏ ‏الْمُعَقَّلَةِ ‏ ‏إِنْ تَعَاهَدَهَا صَاحِبُهَا ‏ ‏بِعُقُلِهَا ‏ ‏أَمْسَكَهَا عَلَيْهِ وَإِنْ أَطْلَقَ ‏ ‏عُقُلَهَا ‏ ‏ذَهَبَتْ ‏","","",""],[4614,4614,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَأْتِي ‏ ‏قُبَاءً ‏ ‏رَاكِبًا وَمَاشِيًا ‏","","",""],[4615,4615,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سِيرِينَ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏صَلَاةُ الْمَغْرِبِ وِتْرُ النَّهَارِ فَأَوْتِرُوا صَلَاةَ اللَّيْلِ ‏","","",""],[4616,4616,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏سُلَيْمَانُ التَّيْمِيُّ ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏صَلَاةُ اللَّيْلِ مَثْنَى مَثْنَى فَإِذَا خِفْتَ الصُّبْحَ ‏ ‏فَأَوْتِرْ ‏ ‏بِوَاحِدَةٍ ‏","","",""],[4617,4617,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدُ بْنُ زِيَادٍ الشَّيْبَانِيُّ ‏ ‏حَدَّثَنَا ‏ ‏زِيَادُ بْنُ صُبَيْحٍ الْحَنَفِيُّ ‏ ‏قَالَ ‏ ‏كُنْتُ قَائِمًا أُصَلِّي إِلَى الْبَيْتِ وَشَيْخٌ إِلَى جَانِبِي فَأَطَلْتُ الصَّلَاةَ فَوَضَعْتُ يَدَيَّ عَلَى خَصْرِي فَضَرَبَ الشَّيْخُ صَدْرِي بِيَدِهِ ضَرْبَةً لَا ‏ ‏يَأْلُو ‏ ‏فَقُلْتُ فِي نَفْسِي مَا ‏ ‏رَابَهُ ‏ ‏مِنِّي فَأَسْرَعْتُ ‏ ‏الِانْصِرَافَ فَإِذَا غُلَامٌ خَلْفَهُ قَاعِدٌ فَقُلْتُ مَنْ هَذَا الشَّيْخُ قَالَ هَذَا ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏فَجَلَسْتُ حَتَّى انْصَرَفَ فَقُلْتُ ‏ ‏أَبَا عَبْدِ الرَّحْمَنِ ‏ ‏مَا ‏ ‏رَابَكَ ‏ ‏مِنِّي قَالَ أَنْتَ هُوَ قُلْتُ نَعَمْ قَالَ ‏ ‏ذَاكَ ‏ ‏الصَّلْبُ ‏ ‏فِي الصَّلَاةِ وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنْهَى عَنْهُ ‏","","",""],[4618,4618,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ عَبْدِ اللَّهِ بْنِ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ حُسَيْنٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَبِيحَةَ ‏ ‏عَرَفَةَ ‏ ‏مِنَّا الْمُكَبِّرُ وَمِنَّا ‏ ‏الْمُهِلُّ ‏ ‏أَمَّا نَحْنُ فَنُكَبِّرُ قَالَ قُلْتُ الْعَجَبُ لَكُمْ كَيْفَ لَمْ تَسْأَلُوهُ كَيْفَ صَنَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[4619,4619,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏حَجَّاجُ بْنُ أَرْطَاةَ ‏ ‏عَنْ ‏ ‏وَبَرَةَ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏أَمَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِقَتْلِ الذِّئْبِ لِلْمُحْرِمِ ‏ ‏يَعْنِي وَالْفَأْرَةَ وَالْغُرَابَ وَالْحِدَأَ ‏ ‏فَقِيلَ لَهُ فَالْحَيَّةُ وَالْعَقْرَبُ فَقَالَ قَدْ كَانَ يُقَالُ ذَاكَ ‏","","",""],[4620,4620,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ بْنِ خَالِدٍ الْمَخْزُومِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَجُلًا اشْتَرَى نَخْلًا قَدْ ‏ ‏أَبَّرَهَا ‏ ‏صَاحِبُهَا ‏ ‏فَخَاصَمَهُ ‏ ‏إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَضَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ الثَّمَرَةَ لِصَاحِبِهَا الَّذِي ‏ ‏أَبَّرَهَا ‏ ‏إِلَّا أَنْ يَشْتَرِطَ الْمُشْتَرِي ‏","","",""],[4621,4621,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏جَرِيرُ بْنُ حَازِمٍ ‏ ‏وَإِسْحَاقُ بْنُ عِيسَى ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرُ بْنُ حَازِمٍ ‏ ‏عَنِ ‏ ‏الزُّبَيْرِ بْنِ الْخِرِّيتِ ‏ ‏عَنِ ‏ ‏الْحَسَنِ بْنِ هَادِيَةَ ‏ ‏قَالَ ‏ ‏لَقِيتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏قَالَ ‏ ‏إِسْحَاقُ ‏ ‏فَقَالَ لِي مِمَّنْ أَنْتَ قُلْتُ مِنْ أَهْلِ ‏ ‏عُمَانَ ‏ ‏قَالَ مِنْ أَهْلِ ‏ ‏عُمَانَ ‏ ‏قُلْتُ نَعَمْ قَالَ أَفَلَا أُحَدِّثُكَ مَا سَمِعْتُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُلْتُ بَلَى ‏ ‏فَقَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنِّي لَأَعْلَمُ أَرْضًا يُقَالُ لَهَا ‏ ‏عُمَانُ ‏ ‏يَنْضَحُ ‏ ‏بِجَانِبِهَا ‏ ‏وَقَالَ ‏ ‏إِسْحَاقُ ‏ ‏بِنَاحِيَتِهَا ‏ ‏الْبَحْرُ الْحَجَّةُ مِنْهَا أَفْضَلُ مِنْ حَجَّتَيْنِ مِنْ غَيْرِهَا ‏","","",""],[4622,4622,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏الْحَجَّاجُ بْنُ أَرْطَاةَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَفَعَ ‏ ‏خَيْبَرَ ‏ ‏إِلَى أَهْلِهَا ‏ ‏بِالشَّطْرِ ‏ ‏فَلَمْ تَزَلْ مَعَهُمْ حَيَاةَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كُلَّهَا وَحَيَاةَ ‏ ‏أَبِي بَكْرٍ ‏ ‏وَحَيَاةَ ‏ ‏عُمَرَ ‏ ‏حَتَّى بَعَثَنِي ‏ ‏عُمَرُ ‏ ‏لِأُقَاسِمَهُمْ فَسَحَرُونِي ‏ ‏فَتَكَوَّعَتْ ‏ ‏يَدِي فَانْتَزَعَهَا ‏ ‏عُمَرُ ‏ ‏مِنْهُمْ ‏","","",""],[4623,4623,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏عَنْ ‏ ‏هَمَّامٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏أَرَادَتْ أَنْ تَشْتَرِيَ ‏ ‏بَرِيرَةَ ‏ ‏فَأَبَى أَهْلُهَا أَنْ يَبِيعُوهَا إِلَّا أَنْ يَكُونَ لَهُمْ ‏ ‏وَلَاؤُهَا ‏ ‏فَذَكَرَتْ ذَلِكَ ‏ ‏عَائِشَةُ ‏ ‏لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اشْتَرِيهَا فَأَعْتِقِيهَا فَإِنَّمَا ‏ ‏الْوَلَاءُ ‏ ‏لِمَنْ أَعْطَى الثَّمَنَ ‏","","",""],[4624,4624,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏جَرِيرُ بْنُ حَازِمٍ ‏ ‏حَدَّثَنَا ‏ ‏نَافِعٌ ‏ ‏قَالَ ‏ ‏وَجَدَ ‏ ‏ابْنُ عُمَرَ ‏ ‏الْقُرَّ ‏ ‏وَهُوَ ‏ ‏مُحْرِمٌ ‏ ‏فَقَالَ أَلْقِ عَلَيَّ ثَوْبًا فَأَلْقَيْتُ عَلَيْهِ ‏ ‏بُرْنُسًا ‏ ‏فَأَخَّرَهُ وَقَالَ ‏ ‏تُلْقِي عَلَيَّ ثَوْبًا قَدْ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يَلْبَسَهُ ‏ ‏الْمُحْرِمُ ‏","","",""],[4625,4625,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاذٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عَوْنٍ ‏ ‏قَالَ كَتَبْتُ إِلَى ‏ ‏نَافِعٍ ‏ ‏أَسْأَلُهُ هَلْ كَانَتْ الدَّعْوَةُ قَبْلَ الْقِتَالِ قَالَ فَكَتَبَ إِلَيَّ إِنَّ ذَاكَ كَانَ فِي أَوَّلِ الْإِسْلَامِ وَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ ‏ ‏أَغَارَ ‏ ‏عَلَى ‏ ‏بَنِي الْمُصْطَلِقِ ‏ ‏وَهُمْ ‏ ‏غَارُّونَ ‏ ‏وَأَنْعَامُهُمْ تُسْقَى عَلَى الْمَاءِ فَقَتَلَ مُقَاتِلَتَهُمْ ‏ ‏وَسَبَى ‏ ‏سَبْيَهُمْ ‏ ‏وَأَصَابَ يَوْمَئِذٍ ‏ ‏جُوَيْرِيَةَ ابْنَةَ الْحَارِثِ ‏ ‏وَحَدَّثَنِي ‏ ‏بِهَذَا الْحَدِيثِ ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏وَكَانَ فِي ذَلِكَ الْجَيْشِ ‏","","",""],[4626,4626,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَنْبَأَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏خُبَيْبِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ خُبَيْبٍ ‏ ‏عَنْ ‏ ‏حَفْصِ بْنِ عَاصِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏صَلَّيْتُ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَبِي بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏وَعُثْمَانَ ‏ ‏سِتَّ سِنِينَ ‏ ‏بِمِنًى ‏ ‏فَصَلَّوْا صَلَاةَ الْمُسَافِرِ ‏","","",""],[4627,4627,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَارِبِ بْنِ دِثَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ مَثَلَ الْمُؤْمِنِ مَثَلُ شَجَرَةٍ لَا يَسْقُطُ وَرَقُهَا فَمَا هِيَ قَالَ فَقَالُوا وَقَالُوا فَلَمْ يُصِيبُوا وَأَرَدْتُ أَنْ أَقُولَ هِيَ النَّخْلَةُ فَاسْتَحْيَيْتُ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هِيَ النَّخْلَةُ ‏","","",""],[4628,4628,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي اللَّيْلَ مَثْنَى مَثْنَى ثُمَّ يُوتِرُ بِرَكْعَةٍ مِنْ آخِرِ اللَّيْلِ ثُمَّ يَقُومُ كَأَنَّ الْأَذَانَ وَالْإِقَامَةَ فِي أُذُنَيْهِ ‏","","",""],[4629,4629,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنْ ‏ ‏أَبِي حَنْظَلَةَ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏عَنْ الصَّلَاةِ فِي السَّفَرِ فَقَالَ ‏ ‏الصَّلَاةُ فِي السَّفَرِ رَكْعَتَيْنِ فَقَالَ إِنَّا آمِنُونَ لَا نَخَافُ أَحَدًا قَالَ سُنَّةُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[4630,4630,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏يَقُومُ النَّاسُ لِرَبِّ الْعَالَمِينَ لِعَظَمَةِ الرَّحْمَنِ تَبَارَكَ وَتَعَالَى يَوْمَ الْقِيَامَةِ حَتَّى إِنَّ الْعَرَقَ ‏ ‏لَيُلْجِمُ ‏ ‏الرِّجَالَ إِلَى أَنْصَافِ آذَانِهِمْ ‏","","",""],[4631,4631,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كُلُّ مُسْكِرٍ خَمْرٌ وَكُلُّ مُسْكِرٍ حَرَامٌ ‏","","",""],[4632,4632,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدٌ يَعْنِي ابْنَ عَمْرٍو ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ عَبْدِ الرَّحْمَنِ بْنِ حَاطِبٍ ‏ ‏أَنَّهُ حَدَّثَهُمْ عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّهُ قَالَ ‏ ‏وَقَفَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى ‏ ‏الْقَلِيبِ ‏ ‏يَوْمَ ‏ ‏بَدْرٍ ‏ ‏فَقَالَ يَا فُلَانُ يَا فُلَانُ هَلْ وَجَدْتُمْ مَا ‏ ‏وَعَدَ ‏ ‏رَبُّكُمْ حَقًّا أَمَا وَاللَّهِ إِنَّهُمْ الْآنَ لَيَسْمَعُونَ كَلَامِي قَالَ ‏ ‏يَحْيَى ‏ ‏فَقَالَتْ ‏ ‏عَائِشَةُ ‏ ‏غَفَرَ اللَّهُ ‏ ‏لِأَبِي عَبْدِ الرَّحْمَنِ ‏ ‏إِنَّهُ ‏ ‏وَهِلَ ‏ ‏إِنَّمَا قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَاللَّهِ إِنَّهُمْ لَيَعْلَمُونَ الْآنَ أَنَّ الَّذِي كُنْتُ أَقُولُ لَهُمْ حَقًّا وَإِنَّ اللَّهَ تَعَالَى يَقُولُ ‏ { ‏إِنَّكَ لَا تُسْمِعُ الْمَوْتَى ‏} { ‏وَمَا أَنْتَ بِمُسْمِعٍ مَنْ فِي الْقُبُورِ ‏}","","",""],[4633,4633,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ عَبْدِ الرَّحْمَنِ بْنِ حَاطِبٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏مَرَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِقَبْرٍ فَقَالَ إِنَّ هَذَا لَيُعَذَّبُ الْآنَ بِبُكَاءِ أَهْلِهِ عَلَيْهِ فَقَالَتْ ‏ ‏عَائِشَةُ ‏ ‏غَفَرَ اللَّهُ ‏ ‏لِأَبِي عَبْدِ الرَّحْمَنِ ‏ ‏إِنَّهُ ‏ ‏وَهِلَ ‏ ‏إِنَّ اللَّهَ تَعَالَى يَقُولُ ‏ { ‏وَلَا ‏ ‏تَزِرُ ‏ ‏وَازِرَةٌ ‏ ‏وِزْرَ ‏ ‏أُخْرَى ‏} ‏إِنَّمَا قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ هَذَا لَيُعَذَّبُ الْآنَ وَأَهْلُهُ يَبْكُونَ عَلَيْهِ ‏","","",""],[4634,4634,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدٌ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ عَبْدِ الرَّحْمَنِ بْنِ حَاطِبٍ ‏ ‏قَالَ قَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الشَّهْرُ تِسْعٌ وَعِشْرُونَ وَصَفَّقَ بِيَدَيْهِ مَرَّتَيْنِ ثُمَّ صَفَّقَ الثَّالِثَةَ وَقَبَضَ إِبْهَامَهُ فَقَالَتْ ‏ ‏عَائِشَةُ ‏ ‏غَفَرَ اللَّهُ ‏ ‏لِأَبِي عَبْدِ الرَّحْمَنِ ‏ ‏إِنَّهُ ‏ ‏وَهِلَ ‏ ‏إِنَّمَا هَجَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نِسَاءَهُ شَهْرًا فَنَزَلَ لِتِسْعٍ وَعِشْرِينَ فَقَالُوا يَا رَسُولَ اللَّهِ إِنَّكَ نَزَلَتْ لِتِسْعٍ وَعِشْرِينَ فَقَالَ ‏ ‏إِنَّ الشَّهْرَ يَكُونُ تِسْعًا وَعِشْرِينَ ‏","","",""],[4635,4635,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنْ ‏ ‏سَالِمٍ الْبَرَّادِ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ صَلَّى عَلَى جَنَازَةٍ فَلَهُ ‏ ‏قِيرَاطٌ ‏ ‏فَسُئِلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا ‏ ‏الْقِيرَاطُ ‏ ‏قَالَ مِثْلُ ‏ ‏أُحُدٍ ‏","","",""],[4636,4636,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدٌ يَعْنِي ابْنَ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ عَلَى هَذَا الْمِنْبَرِ وَهُوَ ‏ ‏يَنْهَى النَّاسَ إِذَا أَحْرَمُوا عَمَّا يُكْرَهُ لَهُمْ لَا تَلْبَسُوا الْعَمَائِمَ وَلَا الْقُمُصَ وَلَا السَّرَاوِيلَاتِ وَلَا ‏ ‏الْبَرَانِسَ ‏ ‏وَلَا الْخُفَّيْنِ إِلَّا أَنْ يُضْطَرَّ مُضْطَرٌّ إِلَيْهِمَا فَيَقْطَعَهُمَا أَسْفَلَ مِنْ الْكَعْبَيْنِ وَلَا ثَوْبًا ‏ ‏مَسَّهُ ‏ ‏الْوَرْسُ ‏ ‏وَلَا ‏ ‏الزَّعْفَرَانُ ‏ ‏قَالَ وَسَمِعْتُهُ يَنْهَى النِّسَاءَ عَنْ الْقُفَّازِ ‏ ‏وَالنِّقَابِ ‏ ‏وَمَا مَسَّ ‏ ‏الْوَرْسُ ‏ ‏وَالزَّعْفَرَانُ ‏ ‏مِنْ الثِّيَابِ ‏","","",""],[4637,4637,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّهُ حَدَّثَهُمْ عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَصْلُحُ بَيْعُ الثَّمَرِ حَتَّى ‏ ‏يَتَبَيَّنَ ‏ ‏صَلَاحُهُ ‏","","",""],[4638,4638,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ يَعْنِي ابْنَ حُسَيْنٍ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ ‏ ‏ابْنِ عُمَرَ ‏ ‏فِي سَفَرٍ ‏ ‏فَمَرَّ بِمَكَانٍ ‏ ‏فَحَادَ ‏ ‏عَنْهُ فَسُئِلَ لِمَ فَعَلْتَ فَقَالَ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَعَلَ هَذَا فَفَعَلْتُ ‏","","",""],[4639,4639,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى يَعْنِي ابْنَ سَعِيدٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ يَحْيَىِ بْنِ حَبَّانَ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏رَجُلًا ‏ ‏أَخْبَرَهُ عَنْ ‏ ‏أَبِيهِ ‏ ‏يَحْيَى ‏ ‏أَنَّهُ كَانَ مَعَ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏وَأَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏قَالَ لَهُ فِي ‏ ‏الْفِتْنَةِ ‏ ‏لَا تَرَوْنَ الْقَتْلَ شَيْئًا ‏ ‏وَقَالَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِلثَّمَادَةِ ‏ ‏لَا ‏ ‏يَنْتَجِي ‏ ‏اثْنَانِ دُونَ صَاحِبِهِمَا ‏","","",""],[4640,4640,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏عَنْ ‏ ‏أَبِي جَعْفَرٍ مُحَمَّدِ بْنِ عَلِيٍّ ‏ ‏قَالَ ‏ ‏بَيْنَمَا ‏ ‏عُبَيْدُ بْنُ عُمَيْرٍ ‏ ‏يَقُصُّ وَعِنْدَهُ ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏فَقَالَ ‏ ‏عُبَيْدُ بْنُ عُمَيْرٍ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَثَلُ الْمُنَافِقِ كَشَاةٍ مِنْ بَيْنِ ‏ ‏رَبِيضَيْنِ ‏ ‏إِذَا ‏ ‏أَتَتْ ‏ ‏هَؤُلَاءِ نَطَحْنَهَا وَإِذَا أَتَتْ هَؤُلَاءِ نَطَحْنَهَا فَقَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏لَيْسَ كَذَلِكَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّمَا قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَشَاةٍ بَيْنَ غَنَمَيْنِ قَالَ فَاحْتَفَظَ الشَّيْخُ وَغَضِبَ فَلَمَّا رَأَى ذَلِكَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ أَمَا إِنِّي لَوْ لَمْ أَسْمَعْهُ لَمْ أَرُدَّ ذَلِكَ عَلَيْكَ ‏","","",""],[4641,4641,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ عَوْنٍ ‏ ‏قَالَ كَتَبْتُ إِلَى ‏ ‏نَافِعٍ ‏ ‏أَسْأَلُهُ مَا أَقْعَدَ ‏ ‏ابْنَ عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏عَنْ الْغَزْوِ ‏ ‏أَوْ عَنْ الْقَوْمِ ‏ ‏إِذَا غَزَوْا بِمَا يَدْعُونَ الْعَدُوَّ قَبْلَ أَنْ يُقَاتِلُوهُمْ وَهَلْ يَحْمِلُ الرَّجُلُ إِذَا كَانَ فِي الْكَتِيبَةِ بِغَيْرِ إِذْنِ إِمَامِهِ فَكَتَبَ إِلَيَّ إِنَّ ‏ ‏ابْنَ عُمَرَ ‏ ‏قَدْ كَانَ يَغْزُو وَلَدُهُ وَيَحْمِلُ عَلَى الظَّهْرِ وَكَانَ يَقُولُ إِنَّ أَفْضَلَ الْعَمَلِ بَعْدَ الصَّلَاةِ الْجِهَادُ فِي سَبِيلِ اللَّهِ تَعَالَى وَمَا أَقْعَدَ ‏ ‏ابْنَ عُمَرَ ‏ ‏عَنْ الْغَزْوِ إِلَّا وَصَايَا ‏ ‏لِعُمَرَ ‏ ‏وَصِبْيَانٌ صِغَارٌ ‏ ‏وَضَيْعَةٌ ‏ ‏كَثِيرَةٌ وَقَدْ ‏ ‏أَغَارَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى ‏ ‏بَنِي الْمُصْطَلِقِ ‏ ‏وَهُمْ ‏ ‏غَارُّونَ ‏ ‏يَسْقُونَ عَلَى نَعَمِهِمْ فَقَتَلَ مُقَاتِلَتَهُمْ وَسَبَى سَبَايَاهُمْ وَأَصَابَ ‏ ‏جُوَيْرِيَةَ بِنْتَ الْحَارِثِ ‏ ‏قَالَ فَحَدَّثَنِي بِهَذَا الْحَدِيثِ ‏ ‏ابْنُ عُمَرَ ‏ ‏وَكَانَ فِي ذَلِكَ الْجَيْشِ وَإِنَّمَا كَانُوا يُدْعَوْنَ فِي أَوَّلِ الْإِسْلَامِ وَأَمَّا الرَّجُلُ فَلَا يَحْمِلُ عَلَى الْكَتِيبَةِ إِلَّا بِإِذْنِ إِمَامِهِ ‏","","",""],[4642,4642,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ ‏ ‏يَتَنَاجَى ‏ ‏اثْنَانِ ‏ ‏دُونَ ‏ ‏الثَّالِثِ إِذَا لَمْ يَكُنْ مَعَهُمْ غَيْرُهُمْ قَالَ وَنَهَى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يَخْلُفَ الرَّجُلُ الرَّجُلَ فِي مَجْلِسِهِ وَقَالَ إِذَا رَجَعَ فَهُوَ أَحَقُّ بِهِ ‏","","",""],[4643,4643,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِذَا نَعَسَ أَحَدُكُمْ فِي الْمَسْجِدِ يَوْمَ الْجُمُعَةِ فَلْيَتَحَوَّلْ مِنْ مَجْلِسِهِ ذَلِكَ إِلَى غَيْرِهِ ‏","","",""],[4644,4644,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏وَعُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏حَدَّثَاهُ عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏خَمْسٌ لَا ‏ ‏جُنَاحَ ‏ ‏عَلَى أَحَدٍ فِي قَتْلِهِنَّ الْغُرَابُ وَالْفَأْرَةُ وَالْحِدَأَةُ وَالْعَقْرَبُ وَالْكَلْبُ ‏ ‏الْعَقُورُ ‏","","",""],[4645,4645,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏رَأَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الْقِبْلَةِ ‏ ‏نُخَامَةً ‏ ‏فَأَخَذَ عُودًا أَوْ حَصَاةً فَحَكَّهَا بِهِ ثُمَّ قَالَ ‏ ‏إِذَا قَامَ أَحَدُكُمْ ‏ ‏يُصَلِّي فَلَا يَبْصُقْ فِي قِبْلَتِهِ فَإِنَّمَا ‏ ‏يُنَاجِي ‏ ‏رَبَّهُ تَبَارَكَ وَتَعَالَى ‏","","",""],[4646,4646,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏صَلَاةُ اللَّيْلِ مَثْنَى مَثْنَى ‏ ‏وَالْوِتْرُ ‏ ‏رَكْعَةٌ مِنْ آخِرِ اللَّيْلِ ‏","","",""],[4647,4647,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الدَّجَّالُ ‏ ‏أَعْوَرُ الْعَيْنِ كَأَنَّهَا عِنَبَةٌ ‏ ‏طَافِيَةٌ ‏","","",""],[4648,4648,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏أَصْبَغُ بْنُ زَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بِشْرٍ ‏ ‏عَنْ ‏ ‏أَبِي الزَّاهِرِيَّةِ ‏ ‏عَنْ ‏ ‏كَثِيرِ بْنِ مُرَّةَ الْحَضْرَمِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ ‏ ‏احْتَكَرَ ‏ ‏طَعَامًا أَرْبَعِينَ لَيْلَةً فَقَدْ بَرِئَ مِنْ اللَّهِ تَعَالَى وَبَرِئَ اللَّهُ تَعَالَى مِنْهُ وَأَيُّمَا أَهْلُ ‏ ‏عَرْصَةٍ ‏ ‏أَصْبَحَ فِيهِمْ امْرُؤٌ جَائِعٌ فَقَدْ بَرِئَتْ مِنْهُمْ ‏ ‏ذِمَّةُ ‏ ‏اللَّهِ تَعَالَى ‏","","",""],[4649,4649,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّهُ كَانَ ‏ ‏يَكْرَهُ ‏ ‏الِاشْتِرَاطَ فِي الْحَجِّ وَيَقُولُ أَمَا حَسْبُكُمْ ‏ ‏سُنَّةَ ‏ ‏نَبِيِّكُمْ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّهُ لَمْ يَشْتَرِطْ ‏","","",""],[4650,4650,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏وَعُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏سُئِلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الضَّبِّ فَقَالَ ‏ ‏لَسْتُ بِآكِلِهِ وَلَا مُحَرِّمِهِ ‏","","",""],[4651,4651,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّهُ سَأَلَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَشْتَرِي الذَّهَبَ بِالْفِضَّةِ فَقَالَ ‏ ‏إِذَا أَخَذْتَ وَاحِدًا مِنْهُمَا فَلَا يُفَارِقْكَ صَاحِبُكَ وَبَيْنَكَ وَبَيْنَهُ ‏ ‏لَبْسٌ ‏","","",""],[4652,4652,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏دَاوُدُ يَعْنِي ابْنَ قَيْسٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏قَالَ ‏ ‏أَرْسَلَنِي أَبِي إِلَى ‏ ‏ابْنِ عُمَرَ ‏ ‏فَقُلْتُ أَأَدْخُلُ فَعَرَفَ صَوْتِي فَقَالَ أَيْ بُنَيَّ إِذَا أَتَيْتَ إِلَى قَوْمٍ فَقُلْ السَّلَامُ عَلَيْكُمْ فَإِنْ رَدُّوا عَلَيْكَ فَقُلْ أَأَدْخُلُ قَالَ ثُمَّ رَأَى ابْنَهُ وَاقِدًا يَجُرُّ إِزَارَهُ فَقَالَ ارْفَعْ إِزَارَكَ فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ جَرَّ ثَوْبَهُ مِنْ ‏ ‏الْخُيَلَاءِ ‏ ‏لَمْ يَنْظُرْ اللَّهُ إِلَيْهِ ‏","","",""],[4653,4653,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏يَتَحَرَّ ‏ ‏أَحَدُكُمْ أَنْ يُصَلِّيَ عِنْدَ طُلُوعِ الشَّمْسِ وَلَا عِنْدَ غُرُوبِهَا ‏","","",""],[4654,4654,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ عُبَيْدِ اللَّهِ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَكَلَ أَحَدُكُمْ فَلْيَأْكُلْ بِيَمِينِهِ وَإِذَا شَرِبَ فَلْيَشْرَبْ بِيَمِينِهِ فَإِنَّ الشَّيْطَانَ يَأْكُلُ بِشِمَالِهِ وَيَشْرَبُ بِشِمَالِهِ ‏","","",""],[4655,4655,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏مَا تَرَكْتُ ‏ ‏اسْتِلَامَ ‏ ‏الرُّكْنَيْنِ فِي رَخَاءٍ وَلَا شِدَّةٍ مُنْذُ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَسْتَلِمُهُمَا ‏ ‏قَالَ ‏ ‏مَعْمَرٌ ‏ ‏وَأَخْبَرَنِي ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏مِثْلَهُ ‏","","",""],[4656,4656,"","","‏ ‏قَالَ ‏ ‏و حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَلَقَ فِي حَجَّتِهِ ‏ ‏قَالَ ‏ ‏و حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏","","",""],[4657,4657,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏دَخَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ فَتْحِ ‏ ‏مَكَّةَ ‏ ‏عَلَى نَاقَةٍ ‏ ‏لِأُسَامَةَ بْنِ زَيْدٍ ‏ ‏حَتَّى ‏ ‏أَنَاخَ ‏ ‏بِفِنَاءِ ‏ ‏الْكَعْبَةِ ‏ ‏فَدَعَا ‏ ‏عُثْمَانَ بْنَ طَلْحَةَ ‏ ‏بِالْمِفْتَاحِ فَجَاءَ بِهِ فَفَتَحَ فَدَخَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأُسَامَةُ ‏ ‏وَبِلَالٌ ‏ ‏وَعُثْمَانُ بْنُ طَلْحَةَ ‏ ‏فَأَجَافُوا ‏ ‏عَلَيْهِمْ الْبَابَ ‏ ‏مَلِيًّا ‏ ‏ثُمَّ فَتَحُوهُ قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏فَبَادَرْتُ ‏ ‏النَّاسَ فَوَجَدْتُ ‏ ‏بِلَالًا ‏ ‏عَلَى الْبَابِ قَائِمًا فَقُلْتُ أَيْنَ صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏بَيْنَ الْعَمُودَيْنِ الْمُقَدَّمَيْنِ قَالَ وَنَسِيتُ أَنْ أَسْأَلَهُ كَمْ صَلَّى ‏","","",""],[4658,4658,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَذِنَ لِضَعَفَةِ النَّاسِ مِنْ ‏ ‏الْمُزْدَلِفَةِ ‏ ‏بِلَيْلٍ ‏","","",""],[4659,4659,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَالِكٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏صَلَّيْتُ مَعَهُ الْمَغْرِبَ ثَلَاثًا وَالْعِشَاءَ رَكْعَتَيْنِ بِإِقَامَةٍ وَاحِدَةٍ فَقَالَ لَهُ ‏ ‏مَالِكُ بْنُ خَالِدٍ الْحَارِثِيُّ ‏ ‏مَا هَذِهِ الصَّلَاةُ يَا ‏ ‏أَبَا عَبْدِ الرَّحْمَنِ ‏ ‏قَالَ صَلَّيْتُهَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي هَذَا الْمَكَانِ بِإِقَامَةٍ وَاحِدَةٍ ‏","","",""],[4660,4660,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ كُهَيْلٍ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏ح ‏ ‏و عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَالِكٍ الْأَسَدِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَمَعَ بَيْنَ الْمَغْرِبِ وَالْعِشَاءِ ‏ ‏بِجَمْعٍ ‏ ‏صَلَّى الْمَغْرِبَ ثَلَاثًا وَالْعِشَاءَ رَكْعَتَيْنِ بِإِقَامَةٍ وَاحِدَةٍ ‏","","",""],[4661,4661,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُلَبِّي ‏ ‏لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ لَبَّيْكَ لَا شَرِيكَ لَكَ لَبَّيْكَ إِنَّ الْحَمْدَ وَالنِّعْمَةَ لَكَ وَالْمُلْكَ لَا شَرِيكَ لَكَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏وَمَالِكٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏","","",""],[4662,4662,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ يَوْمَ ‏ ‏الْحُدَيْبِيَةِ ‏ ‏اللَّهُمَّ اغْفِرْ لِلْمُحَلِّقِينَ فَقَالَ رَجُلٌ وَالْمُقَصِّرِينَ فَقَالَ اللَّهُمَّ اغْفِرْ لِلْمُحَلِّقِينَ فَقَالَ وَلِلْمُقَصِّرِينَ حَتَّى قَالَهَا ثَلَاثًا أَوْ أَرْبَعًا ثُمَّ قَالَ وَلِلْمُقَصِّرِينَ ‏","","",""],[4663,4663,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَفَاضَ ‏ ‏يَوْمَ النَّحْرِ ‏ ‏ثُمَّ رَجَعَ فَصَلَّى الظُّهْرَ ‏ ‏بِمِنًى ‏","","",""],[4664,4664,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَجُلًا نَادَى فَقَالَ يَا رَسُولَ اللَّهِ مَا يَجْتَنِبُ الْمُحْرِمُ مِنْ الثِّيَابِ فَقَالَ ‏ ‏لَا يَلْبَسُ السَّرَاوِيلَ وَلَا الْقَمِيصَ وَلَا ‏ ‏الْبُرْنُسَ ‏ ‏وَلَا الْعِمَامَةَ وَلَا ثَوْبًا ‏ ‏مَسَّهُ ‏ ‏زَعْفَرَانٌ وَلَا ‏ ‏وَرْسٌ ‏ ‏وَلْيُحْرِمْ أَحَدُكُمْ فِي ‏ ‏إِزَارٍ ‏ ‏وَرِدَاءٍ وَنَعْلَيْنِ فَإِنْ لَمْ يَجِدْ نَعْلَيْنِ فَلْيَلْبَسْ خُفَّيْنِ وَلْيَقْطَعْهُمَا حَتَّى يَكُونَا أَسْفَلَ مِنْ ‏ ‏الْعَقِبَيْنِ ‏","","",""],[4665,4665,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى أَنْ تُؤْكَلَ لُحُومُ الْأَضَاحِيِّ بَعْدَ ثَلَاثٍ ‏","","",""],[4666,4666,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ أَعْتَقَ ‏ ‏شِرْكًا ‏ ‏لَهُ فِي عَبْدٍ أُقِيمَ مَا بَقِيَ فِي مَالِهِ ‏","","",""],[4667,4667,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَا حَقُّ امْرِئٍ مُسْلِمٍ تَمُرُّ عَلَيْهِ ثَلَاثُ لَيَالٍ إِلَّا وَوَصِيَّتُهُ عِنْدَهُ ‏","","",""],[4668,4668,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ ‏ ‏عُمَرَ ‏ ‏حَمَلَ عَلَى فَرَسٍ لَهُ فِي سَبِيلِ اللَّهِ ثُمَّ رَآهَا تُبَاعُ فَأَرَادَ أَنْ يَشْتَرِيَهَا فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَعُدْ فِي ‏ ‏صَدَقَتِكَ ‏","","",""],[4669,4669,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏وَالْأَعْمَشِ ‏ ‏وَمَنْصُورٍ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ عُبَيْدَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏عُمَرُ ‏ ‏يَحْلِفُ وَأَبِي فَنَهَاهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ حَلَفَ بِشَيْءٍ دُونَ اللَّهِ تَعَالَى فَقَدْ أَشْرَكَ ‏ ‏وَقَالَ الْآخَرُ ‏ ‏وَهُوَ شِرْكٌ ‏","","",""],[4670,4670,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ أُمَيَّةَ ‏ ‏أَخْبَرَنِي ‏ ‏الثِّقَةُ ‏ ‏أَوْ مَنْ لَا أَتَّهِمُ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّهُ خَطَبَ إِلَى نَسِيبٍ لَهُ ابْنَتَهُ قَالَ فَكَانَ هَوَى أُمِّ الْمَرْأَةِ فِي ‏ ‏ابْنِ عُمَرَ ‏ ‏وَكَانَ هَوَى أَبِيهَا فِي يَتِيمٍ لَهُ قَالَ فَزَوَّجَهَا الْأَبُ يَتِيمَهُ ذَلِكَ فَجَاءَتْ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَتْ ذَلِكَ لَهُ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمِّرُوا النِّسَاءَ فِي بَنَاتِهِنَّ ‏","","",""],[4671,4671,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏عَطَاءٌ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ أَبِي ثَابِتٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّهُ قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏عُمْرَى ‏ ‏وَلَا ‏ ‏رُقْبَى ‏ ‏فَمَنْ ‏ ‏أُعْمِرَ ‏ ‏شَيْئًا أَوْ ‏ ‏أُرْقِبَهُ ‏ ‏فَهُوَ لَهُ حَيَاتَهُ وَمَمَاتَهُ ‏","","",""],[4672,4672,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ أَبِي رَوَّادٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَضَعُ فَصَّ خَاتَمِهِ فِي بَطْنِ الْكَفِّ ‏","","",""],[4673,4673,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ أَبِي رَوَّادٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الْمَسْجِدِ فَرَأَى فِي الْقِبْلَةِ ‏ ‏نُخَامَةً ‏ ‏فَلَمَّا قَضَى صَلَاتَهُ قَالَ ‏ ‏إِنَّ أَحَدَكُمْ إِذَا صَلَّى فِي الْمَسْجِدِ فَإِنَّهُ ‏ ‏يُنَاجِي ‏ ‏رَبَّهُ وَإِنَّ اللَّهَ تَبَارَكَ وَتَعَالَى يَسْتَقْبِلُهُ بِوَجْهِهِ فَلَا ‏ ‏يَتَنَخَّمَنَّ ‏ ‏أَحَدُكُمْ فِي الْقِبْلَةِ وَلَا عَنْ يَمِينِهِ ثُمَّ دَعَا بِعُودٍ فَحَكَّهُ ثُمَّ دَعَا ‏ ‏بِخَلُوقٍ ‏ ‏فَخَضَبَهُ ‏","","",""],[4674,4674,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏الثَّوْرِيُّ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَكْثَرَ مِنْ خَمْسٍ وَعِشْرِينَ مَرَّةً ‏ ‏أَوْ أَكْثَرَ مِنْ عِشْرِينَ مَرَّةً قَالَ ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏وَأَنَا أَشُكُّ ‏ ‏يَقْرَأُ فِي رَكْعَتَيْ الْفَجْرِ ‏ ‏قُلْ يَا أَيُّهَا الْكَافِرُونَ ‏ ‏وَ ‏ ‏قُلْ هُوَ اللَّهُ أَحَدٌ ‏","","",""],[4675,4675,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَنْبَأَنَا ‏ ‏شَيْخٌ ‏ ‏مِنْ أَهْلِ ‏ ‏نَجْرَانَ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ عَبْدِ الرَّحْمَنِ بْنِ الْبَيْلَمَانِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّهُ سَأَلَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ أَنَّ رَجُلًا سَأَلَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏مَا الَّذِي يَجُوزُ فِي الرَّضَاعِ مِنْ الشُّهُودِ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَجُلٌ أَوْ امْرَأَةٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي شَيْبَةَ ‏ ‏عَنْ ‏ ‏مُعْتَمِرٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عُثَيْمٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏يَعْنِي بِهَذَا الْحَدِيثِ ‏","","",""],[4676,4676,"","","‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏و حَدَّثَنَا ‏ ‏أَبُو بَكْرٍ عَبْدُ اللَّهِ بْنُ أَبِي شَيْبَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُعْتَمِرٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عُثَيْمٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ الْبَيْلَمَانِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏سُئِلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا يَجُوزُ فِي الرَّضَاعَةِ مِنْ الشُّهُودِ قَالَ رَجُلٌ وَامْرَأَةٌ ‏","","",""],[4677,4677,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏وَابْنُ بَكْرٍ ‏ ‏قَالَا أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏ابْنُ طَاوُسٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَجُلًا سَأَلَهُ فَقَالَ ‏ ‏أَنَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ ‏ ‏يُنْبَذَ ‏ ‏فِي ‏ ‏الْجَرِّ ‏ ‏وَالدُّبَّاءِ ‏ ‏قَالَ نَعَمْ ‏","","",""],[4678,4678,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَنْبَأَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنْهَى عَنْ ‏ ‏الْجَرِّ ‏ ‏وَالْمُزَفَّتِ ‏ ‏وَالدُّبَّاءِ ‏ ‏قَالَ ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏وَسَمِعْتُ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏يَقُولُ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْجَرِّ ‏ ‏وَالْمُزَفَّتِ ‏ ‏وَالنَّقِيرِ ‏ ‏وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا لَمْ يَجِدْ شَيْئًا ‏ ‏يُنْبَذُ ‏ ‏لَهُ فِيهِ ‏ ‏نُبِذَ ‏ ‏لَهُ فِي ‏ ‏تَوْرٍ ‏ ‏مِنْ حِجَارَةٍ ‏","","",""],[4679,4679,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ الْبُنَانِيِّ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏عَنْ ‏ ‏نَبِيذِ ‏ ‏الْجَرِّ ‏ ‏فَقَالَ حَرَامٌ فَقُلْتُ ‏ ‏أَنَهَى عَنْهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏يَزْعُمُونَ ذَلِكَ ‏","","",""],[4680,4680,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ شَرِبَ الْخَمْرَ فِي الدُّنْيَا ثُمَّ مَاتَ وَهُوَ يَشْرَبُهَا لَمْ يَتُبْ مِنْهَا حَرَّمَهَا اللَّهُ عَلَيْهِ فِي الْآخِرَةِ ‏","","",""],[4681,4681,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُبَيْدِ بْنِ عُمَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ شَرِبَ الْخَمْرَ لَمْ تُقْبَلْ ‏ ‏لَهُ صَلَاةٌ ‏ ‏أَرْبَعِينَ لَيْلَةً فَإِنْ تَابَ تَابَ اللَّهُ عَلَيْهِ فَإِنْ عَادَ كَانَ حَقًّا عَلَى اللَّهِ تَعَالَى أَنْ يَسْقِيَهُ مِنْ نَهَرِ ‏ ‏الْخَبَالِ ‏ ‏قِيلَ وَمَا نَهَرُ الْخَبَالِ قَالَ صَدِيدُ أَهْلِ النَّارِ ‏","","",""],[4682,4682,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا ‏ ‏شِغَارَ ‏ ‏فِي الْإِسْلَامِ ‏","","",""],[4683,4683,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَخْطُبُ يَوْمَ الْجُمُعَةِ مَرَّتَيْنِ بَيْنَهُمَا جَلْسَةٌ ‏","","",""],[4684,4684,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ عَلَى الْمِنْبَرِ يَقُولُ ‏ ‏مَنْ جَاءَ مِنْكُمْ الْجُمُعَةَ فَلْيَغْتَسِلْ ‏","","",""],[4685,4685,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي بَعْدَ الْجُمُعَةِ رَكْعَتَيْنِ فِي بَيْتِهِ ‏","","",""],[4686,4686,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏لَمَّا قَفَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ ‏ ‏حُنَيْنٍ ‏ ‏سَأَلَ ‏ ‏عُمَرُ ‏ ‏عَنْ نَذْرٍ كَانَ نَذَرَهُ فِي الْجَاهِلِيَّةِ اعْتِكَافُ يَوْمٍ ‏ ‏فَأَمَرَ بِهِ فَانْطَلَقَ ‏ ‏عُمَرُ ‏ ‏بَيْنَ يَدَيْهِ قَالَ وَبَعَثَ مَعِي بِجَارِيَةٍ كَانَ أَصَابَهَا يَوْمَ ‏ ‏حُنَيْنٍ ‏ ‏قَالَ فَجَعَلْتُهَا فِي بَعْضِ بُيُوتِ ‏ ‏الْأَعْرَابِ ‏ ‏حِينَ نَزَلْتُ فَإِذَا أَنَا بِسَبْيِ ‏ ‏حُنَيْنٍ ‏ ‏قَدْ خَرَجُوا يَسْعَوْنَ يَقُولُونَ أَعْتَقَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَقَالَ ‏ ‏عُمَرُ ‏ ‏لِعَبْدِ اللَّهِ ‏ ‏اذْهَبْ فَأَرْسِلْهَا قَالَ فَذَهَبْتُ فَأَرْسَلْتُهَا ‏","","",""],[4687,4687,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَثَلُ الْقُرْآنِ إِذَا ‏ ‏عَاهَدَ ‏ ‏عَلَيْهِ صَاحِبُهُ فَقَرَأَهُ بِاللَّيْلِ وَالنَّهَارِ كَمَثَلِ رَجُلٍ لَهُ إِبِلٌ فَإِنْ ‏ ‏عَقَلَهَا ‏ ‏حَفِظَهَا وَإِنْ أَطْلَقَ ‏ ‏عُقُلَهَا ‏ ‏ذَهَبَتْ فَكَذَلِكَ صَاحِبُ الْقُرْآنِ ‏","","",""],[4688,4688,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا حَسَدَ إِلَّا عَلَى اثْنَتَيْنِ رَجُلٌ آتَاهُ اللَّهُ الْقُرْآنَ فَهُوَ يَقُومُ بِهِ ‏ ‏آنَاءَ ‏ ‏اللَّيْلِ ‏ ‏وَآنَاءَ ‏ ‏النَّهَارِ وَرَجُلٌ آتَاهُ اللَّهُ مَالًا فَهُوَ يُنْفِقُ مِنْهُ ‏ ‏آنَاءَ ‏ ‏اللَّيْلِ ‏ ‏وَآنَاءَ ‏ ‏النَّهَارِ ‏","","",""],[4689,4689,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْتَمِسُوا ‏ ‏لَيْلَةَ الْقَدْرِ فِي الْعَشْرِ ‏ ‏الْغَوَابِرِ ‏ ‏فِي التِّسْعِ ‏ ‏الْغَوَابِرِ ‏","","",""],[4690,4690,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدِ بْنِ جُدْعَانَ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ رَبِيعَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏كَانَ مَرَّةً يَقُولُ ‏ ‏ابْنِ مُحَمَّدٍ ‏ ‏وَمَرَّةً يَقُولُ ‏ ‏ابْنِ رَبِيعَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ وَهُوَ عَلَى دَرَجِ ‏ ‏الْكَعْبَةِ ‏ ‏الْحَمْدُ لِلَّهِ الَّذِي أَنْجَزَ وَعْدَهُ وَنَصَرَ عَبْدَهُ وَهَزَمَ الْأَحْزَابَ وَحْدَهُ أَلَا وَإِنَّ كُلَّ مَأْثُرَةٍ كَانَتْ فِي الْجَاهِلِيَّةِ فَإِنَّهَا تَحْتَ قَدَمَيَّ الْيَوْمَ إِلَّا مَا كَانَ مِنْ ‏ ‏سِدَانَةِ ‏ ‏الْبَيْتِ ‏ ‏وَسِقَايَةِ ‏ ‏الْحَاجِّ أَلَا وَإِنَّ مَا بَيْنَ الْعَمْدِ وَالْخَطَإِ وَالْقَتْلِ بِالسَّوْطِ وَالْحَجَرِ فِيهَا مِائَةُ بَعِيرٍ مِنْهَا أَرْبَعُونَ فِي بُطُونِهَا أَوْلَادُهَا ‏","","",""],[4691,4691,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏رَبَاحٌ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏حَمْزَةَ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الشُّؤْمُ فِي ثَلَاثٍ الْفَرَسِ وَالْمَرْأَةِ وَالدَّارِ ‏","","",""],[4692,4692,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏رَبَاحٌ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنْ ‏ ‏صَدَقَةَ الْمَكِّيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اعْتَكَفَ ‏ ‏وَخَطَبَ النَّاسَ فَقَالَ ‏ ‏أَمَا إِنَّ أَحَدَكُمْ إِذَا قَامَ فِي الصَّلَاةِ فَإِنَّهُ ‏ ‏يُنَاجِي ‏ ‏رَبَّهُ فَلْيَعْلَمْ أَحَدُكُمْ مَا ‏ ‏يُنَاجِي ‏ ‏رَبَّهُ وَلَا يَجْهَرْ بَعْضُكُمْ عَلَى بَعْضٍ بِالْقِرَاءَةِ فِي الصَّلَاةِ ‏","","",""],[4693,4693,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ ‏ ‏عُمَرَ ‏ ‏سَأَلَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَلْ يَنَامُ أَحَدُنَا وَهُوَ ‏ ‏جُنُبٌ ‏ ‏فَقَالَ نَعَمْ وَيَتَوَضَّأُ وُضُوءَهُ لِلصَّلَاةِ ‏ ‏قَالَ ‏ ‏نَافِعٌ ‏ ‏فَكَانَ ‏ ‏ابْنُ عُمَرَ ‏ ‏إِذَا أَرَادَ أَنْ يَفْعَلَ شَيْئًا مِنْ ذَلِكَ تَوَضَّأَ وُضُوءَهُ لِلصَّلَاةِ ‏ ‏مَا خَلَا ‏ ‏رِجْلَيْهِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنِي ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ أَنَّ ‏ ‏عُمَرَ ‏ ‏سَأَلَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[4694,4694,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏رَبَاحٌ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى أَنْ ‏ ‏يَتَحَرَّى ‏ ‏أَحَدُكُمْ غُرُوبَ الشَّمْسِ فَيُصَلِّيَ عِنْدَ ذَلِكَ ‏","","",""],[4695,4695,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏رَبَاحٌ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَمْنَعُوا ‏ ‏إِمَاءَ ‏ ‏اللَّهِ أَنْ يَأْتِينَ ‏ ‏أَوْ قَالَ يُصَلِّينَ فِي ‏ ‏الْمَسْجِدِ ‏","","",""],[4696,4696,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏رَبَاحٌ ‏ ‏حَدَّثَنِي ‏ ‏عُمَرُ بْنُ حَبِيبٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي نَجِيحٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَمْنَعَنَّ رَجُلٌ أَهْلَهُ أَنْ يَأْتُوا الْمَسَاجِدَ ‏ ‏فَقَالَ ‏ ‏ابْنٌ لِعَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏فَإِنَّا نَمْنَعُهُنَّ قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏أُحَدِّثُكَ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَتَقُولُ هَذَا قَالَ فَمَا كَلَّمَهُ ‏ ‏عَبْدُ اللَّهِ ‏ ‏حَتَّى مَاتَ ‏","","",""],[4697,4697,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ بَحِيرٍ الْقَاصُّ ‏ ‏أَنَّ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ يَزِيدَ الصَّنْعَانِيَّ ‏ ‏أَخْبَرَهُ أَنَّهُ سَمِعَ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ سَرَّهُ أَنْ يَنْظُرَ إِلَى يَوْمِ الْقِيَامَةِ كَأَنَّهُ رَأْيُ عَيْنٍ فَلْيَقْرَأْ ‏ ‏إِذَا الشَّمْسُ ‏ ‏كُوِّرَتْ ‏ ‏وَ ‏ ‏إِذَا السَّمَاءُ انْفَطَرَتْ ‏ ‏وَ ‏ ‏إِذَا السَّمَاءُ انْشَقَّتْ ‏ ‏وَأَحْسَبُهُ قَالَ وَسُورَةَ ‏ ‏هُودٍ ‏","","",""],[4698,4698,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏صَالِحُ بْنُ كَيْسَانَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَهَلَّ ‏ ‏حِينَ ‏ ‏اسْتَوَتْ ‏ ‏بِهِ ‏ ‏رَاحِلَتُهُ ‏ ‏قَائِمَةً ‏","","",""],[4699,4699,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏أَنَّ ‏ ‏ابْنَ عُمَرَ ‏ ‏كَانَ يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَأْكُلْ أَحَدُكُمْ مِنْ أُضْحِيَّتِهِ فَوْقَ ثَلَاثَةِ أَيَّامٍ ‏","","",""],[4700,4700,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ قَالَ لِي ‏ ‏نَافِعٌ ‏ ‏قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏يُقْتَلُ مِنْ الدَّوَابِّ خَمْسٌ لَا ‏ ‏جُنَاحَ ‏ ‏عَلَى مَنْ قَتَلَهُنَّ فِي قَتْلِهِنَّ الْغُرَابُ وَالْحِدَأَةُ وَالْعَقْرَبُ وَالْكَلْبُ ‏ ‏الْعَقُورُ ‏ ‏وَالْفَأْرَةُ ‏","","",""],[4701,4701,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏حَدَّثَنِي ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏حَدِيثِ ‏ ‏سَالِمِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْتَمِسُوا ‏ ‏لَيْلَةَ الْقَدْرِ فِي السَّبْعِ الْأَوَاخِرِ مِنْ شَهْرِ رَمَضَانَ ‏","","",""],[4702,4702,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏وَابْنُ بَكْرٍ ‏ ‏قَالَا أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ قَالَ ‏ ‏ابْنُ شِهَابٍ ‏ ‏حَدَّثَنِي ‏ ‏سَالِمُ بْنُ عَبْدِ اللَّهِ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏كَانَ يَمْشِي بَيْنَ يَدَيْ الْجِنَازَةِ وَقَدْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَبُو بَكْرٍ ‏ ‏وَعُمَرُ ‏ ‏وَعُثْمَانُ ‏ ‏يَمْشُونَ أَمَامَهَا ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ قَرَأْتُ عَلَى ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏حَدَّثَنِي ‏ ‏زِيَادٌ يَعْنِي ابْنَ سَعْدٍ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏مِثْلَهُ ‏","","",""],[4703,4703,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ بَحِيرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ ‏ ‏وَكَانَ مِنْ أَهْلِ ‏ ‏صَنْعَاءَ ‏ ‏وَكَانَ أَعْلَمَ بِالْحَلَالِ وَالْحَرَامِ مِنْ ‏ ‏وَهْبٍ يَعْنِي ابْنَ مُنَبِّهٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَحَبَّ أَنْ يَنْظُرَ إِلَى يَوْمِ الْقِيَامَةِ فَلْيَقْرَأْ ‏ ‏إِذَا الشَّمْسُ ‏ ‏كُوِّرَتْ ‏","","",""],[4704,4704,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏سَمِعَ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ عَلَى الْمِنْبَرِ ‏ ‏مَنْ جَاءَ مِنْكُمْ الْجُمُعَةَ فَلْيَغْتَسِلْ ‏","","",""],[4705,4705,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏ابْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الثَّمَرِ أَنْ يُبَاعَ حَتَّى ‏ ‏يَبْدُوَ ‏ ‏صَلَاحُهُ ‏","","",""],[4706,4706,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ ‏ ‏اقْتَنَى ‏ ‏كَلْبًا إِلَّا كَلْبَ مَاشِيَةٍ أَوْ كَلْبَ ‏ ‏قَنْصٍ ‏ ‏نَقَصَ مِنْ أَجْرِهِ كُلَّ يَوْمٍ ‏ ‏قِيرَاطَانِ ‏","","",""],[4707,4707,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِابْنِ عُمَرَ ‏ ‏رَجُلٌ ‏ ‏لَاعَنَ ‏ ‏امْرَأَتَهُ فَقَالَ ‏ ‏فَرَّقَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَ أَخَوَيْ ‏ ‏بَنِي الْعَجْلَانِ ‏ ‏وَقَالَ إِنَّ أَحَدَكُمَا كَاذِبٌ فَهَلْ مِنْكُمَا تَائِبٌ ثَلَاثًا ‏","","",""],[4708,4708,"","","‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ أُسَامَةَ ‏ ‏قَالَ ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَامَلَ أَهْلَ ‏ ‏خَيْبَرَ ‏ ‏بِشَطْرِ ‏ ‏مَا خَرَجَ مِنْ زَرْعٍ أَوْ تَمْرٍ فَكَانَ يُعْطِي أَزْوَاجَهُ كُلَّ عَامٍ مِائَةَ ‏ ‏وَسْقٍ ‏ ‏وَثَمَانِينَ ‏ ‏وَسْقًا ‏ ‏مِنْ تَمْرٍ وَعِشْرِينَ ‏ ‏وَسْقًا ‏ ‏مِنْ شَعِيرٍ ‏","","",""],[4709,4709,"","","‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ أُسَامَةَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا أَدْخَلَ رِجْلَهُ فِي ‏ ‏الْغَرْزِ ‏ ‏وَاسْتَوَتْ ‏ ‏بِهِ نَاقَتُهُ قَائِمَةً ‏ ‏أَهَلَّ ‏ ‏مِنْ عِنْدِ مَسْجِدِ ‏ ‏ذِي الْحُلَيْفَةِ ‏","","",""],[4710,4710,"","","‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏قَالَ ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏أَخْبَرَنَا ‏ ‏وَمُحَمَّدُ بْنُ بِشْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَكَرَ ‏ ‏الْمَسِيحَ ‏ ‏قَالَ ‏ ‏ابْنُ بِشْرٍ ‏ ‏فِي حَدِيثِهِ وَذَكَرَ ‏ ‏الدَّجَّالَ ‏ ‏بَيْنَ ‏ ‏ظَهْرَانَيْ ‏ ‏النَّاسِ فَقَالَ ‏ ‏إِنَّ اللَّهَ تَبَارَكَ وَتَعَالَى لَيْسَ بِأَعْوَرَ أَلَا وَإِنَّ ‏ ‏الْمَسِيحَ الدَّجَّالَ ‏ ‏أَعْوَرُ عَيْنِ الْيُمْنَى كَأَنَّ عَيْنَهُ عِنَبَةٌ ‏ ‏طَافِيَةٌ ‏","","",""],[4711,4711,"","","‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ أُسَامَةَ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا دُعِيَ أَحَدُكُمْ إِلَى ‏ ‏وَلِيمَةٍ ‏ ‏فَلْيُجِبْ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ أُسَامَةَ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَذَا الْحَدِيثَ وَهَذَا الْوَصْفَ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏وَحَدَّثَنَا ‏ ‏قَبْلَهُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏وَابْنُ عَوْنٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏صَلَّى بِنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِحْدَى صَلَاتَيْ ‏ ‏الْعَشِيِّ ‏ ‏رَكْعَتَيْنِ ثُمَّ سَلَّمَ فَذَكَرَ الْحَدِيثَ فَلْيُجِبْ ‏","","",""],[4712,4712,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ زَكَرِيَّا بْنِ أَبِي زَائِدَةَ ‏ ‏حَدَّثَنِي ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏بَادِرُوا ‏ ‏الصُّبْحَ ‏ ‏بِالْوِتْرِ ‏","","",""],[4713,4713,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ زَكَرِيَّا ‏ ‏حَدَّثَنِي ‏ ‏مَالِكُ بْنُ أَنَسٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلْحَقَ ابْنَ ‏ ‏الْمُلَاعَنَةِ ‏ ‏بِأُمِّهِ ‏","","",""],[4714,4714,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ زَكَرِيَّا ‏ ‏أَخْبَرَنِي ‏ ‏عَاصِمٌ الْأَحْوَلُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَقِيقٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏بَادِرُوا ‏ ‏الصُّبْحَ ‏ ‏بِالْوَتْرِ ‏","","",""],[4715,4715,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ زَكَرِيَّا ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏أَقَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالْمَدِينَةِ ‏ ‏عَشْرَ سِنِينَ يُضَحِّي ‏","","",""],[4716,4716,"","","‏ ‏حَدَّثَنَا ‏ ‏قُرَّانُ بْنُ تَمَّامٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنِ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصَلِّي عَلَى رَاحِلَتِهِ حَيْثُ تَوَجَّهَتْ بِهِ ‏","","",""],[4717,4717,"","","‏ ‏حَدَّثَنَا ‏ ‏مَرْوَانُ بْنُ مُعَاوِيَةَ الْفَزَارِيُّ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ عُمَرَ بْنِ عَبْدِ الْعَزِيزِ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ جَرِيرٍ ‏ ‏عَنْ ‏ ‏قَزَعَةَ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏وَأَرْسَلَنِي فِي حَاجَةٍ لَهُ فَقَالَ تَعَالَ حَتَّى أُوَدِّعَكَ كَمَا وَدَّعَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَرْسَلَنِي فِي حَاجَةٍ لَهُ فَأَخَذَ بِيَدِي فَقَالَ ‏ ‏أَسْتَوْدِعُ ‏ ‏اللَّهَ دِينَكَ وَأَمَانَتَكَ وَخَوَاتِيمَ عَمَلِكَ ‏","","",""],[4718,4718,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدَةُ بْنُ سُلَيْمَانَ أَبُو مُحَمَّدٍ الْكِلَابِيُّ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَفَ عَلَى ‏ ‏قَلِيبِ بَدْرٍ ‏ ‏فَقَالَ ‏ ‏هَلْ وَجَدْتُمْ مَا وَعَدَكُمْ رَبُّكُمْ حَقًّا ثُمَّ قَالَ إِنَّهُمْ لَيَسْمَعُونَ مَا أَقُولُ ‏ ‏فَذُكِرَ ‏ ‏ذَلِكَ ‏ ‏لِعَائِشَةَ ‏ ‏فَقَالَتْ ‏ ‏وَهِلَ ‏ ‏يَعْنِي ‏ ‏ابْنَ عُمَرَ ‏ ‏إِنَّمَا قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّهُمْ الْآنَ لَيَعْلَمُونَ أَنَّ الَّذِي كُنْتُ أَقُولُ لَهُمْ لَهُوَ الْحَقُّ ‏","","",""],[4719,4719,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدَةُ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِنَّ الْمَيِّتَ لَيُعَذَّبُ بِبُكَاءِ أَهْلِهِ عَلَيْهِ ‏ ‏فَذُكِرَ ‏ ‏ذَلِكَ ‏ ‏لِعَائِشَةَ ‏ ‏فَقَالَتْ ‏ ‏وَهِلَ ‏ ‏يَعْنِي ‏ ‏ابْنَ عُمَرَ ‏ ‏إِنَّمَا ‏ ‏مَرَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى قَبْرٍ فَقَالَ إِنَّ صَاحِبَ هَذَا لَيُعَذَّبُ وَأَهْلُهُ يَبْكُونَ عَلَيْهِ ثُمَّ قَرَأَتْ هَذِهِ الْآيَةَ ‏ { ‏وَلَا ‏ ‏تَزِرُ ‏ ‏وَازِرَةٌ ‏ ‏وِزْرَ ‏ ‏أُخْرَى ‏}","","",""],[4720,4720,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدَةُ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ إِذَا ‏ ‏قَفَلَ ‏ ‏مِنْ الْجُيُوشِ وَالسَّرَايَا أَوْ الْحَجِّ وَالْعُمْرَةِ فَإِذَا أَوْفَى عَلَى ‏ ‏أُرْبِيَّةٍ ‏ ‏كَبَّرَ ثَلَاثًا ثُمَّ قَالَ ‏ ‏لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ ‏ ‏آيِبُونَ ‏ ‏تَائِبُونَ عَابِدُونَ سَاجِدُونَ لِرَبِّنَا حَامِدُونَ صَدَقَ وَعْدَهُ وَنَصَرَ عَبْدَهُ وَهَزَمَ الْأَحْزَابَ وَحْدَهُ ‏","","",""],[4721,4721,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدَةُ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ جَعْفَرِ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُسْأَلُ عَنْ الْمَاءِ يَكُونُ بِأَرْضِ ‏ ‏الْفَلَاةِ ‏ ‏وَمَا ‏ ‏يَنُوبُهُ ‏ ‏مِنْ الدَّوَابِّ وَالسِّبَاعِ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا كَانَ الْمَاءُ قَدْرَ ‏ ‏قُلَّتَيْنِ ‏ ‏لَمْ يَحْمِلْ الْخَبَثَ ‏","","",""],[4722,4722,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدَةُ بْنُ سُلَيْمَانَ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏مَنْ ‏ ‏سَمِعَ ‏ ‏ابْنَ سُرَاقَةَ ‏ ‏يَذْكُرُ عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏مَا رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي قَبْلَ الصَّلَاةِ وَلَا بَعْدَهَا فِي السَّفَرِ ‏","","",""],[4723,4723,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدَةُ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَبَا بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏كَانُوا ‏ ‏يَبْدَءُونَ بِالصَّلَاةِ قَبْلَ الْخُطْبَةِ فِي الْعِيدِ ‏","","",""],[4724,4724,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ يَمَانٍ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏طَافَ طَوَافًا وَاحِدًا لِإِقْرَانِهِ لَمْ يَحِلَّ بَيْنَهُمَا وَاشْتَرَى هَدْيًا مِنْ الطَّرِيقِ مِنْ ‏ ‏قُدَيْدٍ ‏","","",""],[4725,4725,"","","‏ ‏حَدَّثَنَا ‏ ‏الْوَلِيدُ بْنُ مُسْلِمٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ عَبْدِ الْعَزِيزِ ‏ ‏وَمَخْلَدُ بْنُ يَزِيدَ ‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدٌ ‏ ‏الْمَعْنَى ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ مُوسَى ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏مَوْلَى ‏ ‏ابْنِ عُمَرَ ‏ ‏سَمِعَ ‏ ‏ابْنُ عُمَرَ ‏ ‏صَوْتَ زَمَّارَةِ رَاعٍ فَوَضَعَ إِصْبَعَيْهِ فِي أُذُنَيْهِ وَعَدَلَ رَاحِلَتَهُ عَنْ الطَّرِيقِ وَهُوَ يَقُولُ يَا ‏ ‏نَافِعُ ‏ ‏أَتَسْمَعُ فَأَقُولُ نَعَمْ قَالَ ‏ ‏فَيَمْضِي حَتَّى قُلْتُ لَا قَالَ فَوَضَعَ يَدَيْهِ وَأَعَادَ الرَّاحِلَةَ إِلَى الطَّرِيقِ وَقَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَسَمِعَ صَوْتَ زَمَّارَةِ رَاعٍ فَصَنَعَ مِثْلَ هَذَا ‏","","",""],[4726,4726,"","","‏ ‏حَدَّثَنَا ‏ ‏الْوَلِيدُ يَعْنِي ابْنَ مُسْلِمٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏حَدَّثَنِي ‏ ‏الْمُطَّلِبُ بْنُ عَبْدِ اللَّهِ بْنِ حَنْطَبٍ ‏ ‏أَنَّ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏كَانَ ‏ ‏يَتَوَضَّأُ مَرَّةً مَرَّةً وَيُسْنِدُ ذَلِكَ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَّ ‏ ‏ابْنَ عُمَرَ ‏ ‏كَانَ ‏ ‏يَتَوَضَّأُ ثَلَاثًا ثَلَاثًا وَيُسْنِدُ ذَلِكَ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[4727,4727,"","","‏ ‏حَدَّثَنَا ‏ ‏الْوَلِيدُ بْنُ مُسْلِمٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّزَّاقِ بْنِ عُمَرَ الثَّقَفِيِّ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏ابْنَ شِهَابٍ ‏ ‏يُخْبِرُ عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏شَهِدْتُ الْعِيدَ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَصَلَّى ‏ ‏بِلَا أَذَانٍ وَلَا إِقَامَةٍ ‏ ‏ثُمَّ شَهِدْتُ الْعِيدَ مَعَ ‏ ‏أَبِي بَكْرٍ ‏ ‏فَصَلَّى ‏ ‏بِلَا أَذَانٍ وَلَا إِقَامَةٍ ‏ ‏قَالَ ‏ ‏ثُمَّ شَهِدْتُ الْعِيدَ مَعَ ‏ ‏عُمَرَ ‏ ‏فَصَلَّى ‏ ‏بِلَا أَذَانٍ وَلَا إِقَامَةٍ ‏ ‏ثُمَّ شَهِدْتُ الْعِيدَ مَعَ ‏ ‏عُثْمَانَ ‏ ‏فَصَلَّى ‏ ‏بِلَا أَذَانٍ وَلَا إِقَامَةٍ ‏ ‏حَدَّثَنَا ‏ ‏الْوَلِيدُ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ ثَوْبَانَ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏النُّعْمَانَ بْنَ رَاشِدٍ الْجَزَرِيَّ ‏ ‏يُخْبِرُ أَنَّهُ سَمِعَ ‏ ‏ابْنَ شِهَابٍ الزُّهْرِيَّ ‏ ‏يُخْبِرُ عَنْ ‏ ‏سَالِمِ بْنِ عَبْدِ اللَّهِ ‏ ‏يُخْبِرُ عَنْ ‏ ‏أَبِيهِ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏مِثْلَ هَذَا الْحَدِيثِ أَوْ نَحْوَهُ ‏","","",""],[4728,4728,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ عَلِيٍّ ‏ ‏عَنْ ‏ ‏زَائِدَةَ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏مُصْعَبِ بْنِ سَعْدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تُقْبَلُ ‏ ‏صَدَقَةٌ ‏ ‏مِنْ ‏ ‏غُلُولٍ ‏ ‏وَلَا صَلَاةٌ بِغَيْرِ طُهُورٍ ‏","","",""],[4729,4729,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ عَلِيٍّ ‏ ‏عَنْ ‏ ‏زَائِدَةَ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ مُهَاجِرٍ ‏ ‏عَنْ ‏ ‏أَبِي الشَّعْثَاءِ ‏ ‏قَالَ ‏ ‏أَتَيْنَا ‏ ‏ابْنَ عُمَرَ ‏ ‏فِي الْيَوْمِ الْأَوْسَطِ مِنْ أَيَّامِ التَّشْرِيقِ قَالَ فَأُتِيَ بِطَعَامٍ فَدَنَا الْقَوْمُ وَتَنَحَّى ابْنٌ لَهُ قَالَ فَقَالَ لَهُ ادْنُ فَاطْعَمْ قَالَ فَقَالَ إِنِّي صَائِمٌ قَالَ فَقَالَ أَمَا عَلِمْتَ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّهَا أَيَّامُ ‏ ‏طُعْمٍ ‏ ‏وَذِكْرٍ ‏","","",""],[4730,4730,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بِشْرٍ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏وَمَنْ صَلَّى مِنْ أَوَّلِ اللَّيْلِ فَلْيَجْعَلْ آخِرَ صَلَاتِهِ ‏ ‏وِتْرًا ‏ ‏فَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَأْمُرُ بِذَلِكَ ‏","","",""],[4731,4731,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بِشْرٍ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو بَكْرِ بْنُ سَالِمٍ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ أُرِيتُ فِي النَّوْمِ أَنِّي ‏ ‏أَنْزِعُ بِدَلْوِ ‏ ‏بَكْرَةٍ ‏ ‏عَلَى ‏ ‏قَلِيبٍ ‏ ‏فَجَاءَ ‏ ‏أَبُو بَكْرٍ ‏ ‏فَنَزَعَ ‏ ‏ذَنُوبًا ‏ ‏أَوْ ‏ ‏ذَنُوبَيْنِ ‏ ‏وَنَزَعَ نَزْعًا ضَعِيفًا وَاللَّهُ يَغْفِرُ لَهُ ثُمَّ جَاءَ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏فَاسْتَقَى ‏ ‏فَاسْتَحَالَتْ ‏ ‏غَرْبًا ‏ ‏فَلَمْ أَرَ ‏ ‏عَبْقَرِيًّا ‏ ‏مِنْ النَّاسِ ‏ ‏يَفْرِي ‏ ‏فَرِيَّهُ ‏ ‏حَتَّى رَوَّى النَّاسُ وَضَرَبُوا بِعَطَنٍ ‏","","",""],[4732,4732,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بِشْرٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ نَافِعٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْقَزَعِ ‏ ‏قَالَ ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏وَالْقَزَعُ ‏ ‏التَّرْقِيعُ فِي الرَّأْسِ ‏","","",""],[4733,4733,"","","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ ‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ نَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْقَزَعِ ‏","","",""],[4734,4734,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ سُلَيْمَانَ ‏ ‏سَمِعْتُ ‏ ‏حَنْظَلَةَ بْنَ أَبِي سُفْيَانَ الْجُمَحِيَّ ‏ ‏سَمِعْتُ ‏ ‏سَالِمَ بْنَ عَبْدِ اللَّهِ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَأَنْ يَمْتَلِئَ جَوْفُ أَحَدِكُمْ قَيْحًا خَيْرٌ لَهُ مِنْ أَنْ يَمْتَلِئَ شِعْرًا ‏","","",""],[4735,4735,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ سُلَيْمَانَ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ أَبِي رَوَّادٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ فَصَّ خَاتَمِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ فِي بَاطِنِ كَفِّهِ ‏","","",""],[4736,4736,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ سُلَيْمَانَ ‏ ‏سَمِعْتُ ‏ ‏حَنْظَلَةَ بْنَ أَبِي سُفْيَانَ ‏ ‏سَمِعْتُ ‏ ‏سَالِمًا ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَيْتُ عِنْدَ ‏ ‏الْكَعْبَةِ ‏ ‏مِمَّا يَلِي وَجْهَهَا رَجُلًا آدَمَ ‏ ‏سَبْطَ ‏ ‏الرَّأْسِ وَاضِعًا يَدَهُ عَلَى رَجُلَيْنِ ‏ ‏يَسْكُبُ ‏ ‏رَأْسُهُ ‏ ‏أَوْ يَقْطُرُ رَأْسُهُ ‏ ‏فَقُلْتُ مَنْ هَذَا قَالُوا ‏ ‏عِيسَى ابْنُ مَرْيَمَ ‏ ‏أَوْ ‏ ‏الْمَسِيحُ ابْنُ مَرْيَمَ ‏ ‏وَرَأَيْتُ وَرَاءَهُ رَجُلًا أَحْمَرَ أَعْوَرَ عَيْنِ الْيُمْنَى ‏ ‏جَعْدَ ‏ ‏الرَّأْسِ أَشْبَهُ مَنْ رَأَيْتُ بِهِ ‏ ‏ابْنُ قَطَنٍ ‏ ‏فَقُلْتُ مَنْ هَذَا قَالُوا ‏ ‏الْمَسِيحُ الدَّجَّالُ ‏","","",""],[4737,4737,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ سُلَيْمَانَ ‏ ‏وَعَبْدُ اللَّهِ بْنُ الْحَارِثِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَنْظَلَةُ ‏ ‏سَمِعْتُ ‏ ‏سَالِمًا ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏إِنَّ ‏ ‏عُمَرَ بْنَ الْخَطَّابِ ‏ ‏أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِحُلَّةِ ‏ ‏إِسْتَبْرَقٍ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ لَوْ اشْتَرَيْتَ هَذِهِ ‏ ‏الْحُلَّةَ ‏ ‏فَتَلْبَسَهَا ‏ ‏إِذَا قَدِمَ عَلَيْكَ وُفُودُ النَّاسِ فَقَالَ ‏ ‏إِنَّمَا يَلْبَسُ هَذَا مَنْ لَا ‏ ‏خَلَاقَ ‏ ‏لَهُ ثُمَّ أُتِيَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِحُلَلٍ ‏ ‏ثَلَاثٍ فَبَعَثَ إِلَى ‏ ‏عُمَرَ ‏ ‏بِحُلَّةٍ ‏ ‏وَإِلَى ‏ ‏عَلِيٍّ ‏ ‏بِحُلَّةٍ ‏ ‏وَإِلَى ‏ ‏أُسَامَةَ بْنِ زَيْدٍ ‏ ‏بِحُلَّةٍ ‏ ‏فَأَتَى ‏ ‏عُمَرُ ‏ ‏بِحُلَّتِهِ ‏ ‏النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ بَعَثْتَ إِلَيَّ بِهَذِهِ وَقَدْ سَمِعْتُكَ قُلْتَ فِيهَا مَا قُلْتَ قَالَ إِنَّمَا بَعَثْتُ بِهَا إِلَيْكَ لِتَبِيعَهَا أَوْ تُشَقِّقَهَا لِأَهْلِكَ خُمُرًا ‏ ‏قَالَ ‏ ‏إِسْحَاقُ ‏ ‏فِي حَدِيثِهِ وَأَتَاهُ ‏ ‏أُسَامَةُ ‏ ‏وَعَلَيْهِ ‏ ‏الْحُلَّةُ ‏ ‏فَقَالَ إِنِّي لَمْ أَبْعَثْ بِهَا إِلَيْكَ لِتَلْبَسَهَا إِنَّمَا بَعَثْتُ بِهَا إِلَيْكَ لِتَبِيعَهَا ‏ ‏مَا أَدْرِي أَقَالَ ‏ ‏لِأُسَامَةَ ‏ ‏تُشَقِّقُهَا خُمُرًا أَمْ لَا ‏ ‏قَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ الْحَارِثِ ‏ ‏فِي حَدِيثِهِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏سَالِمَ بْنَ عَبْدِ اللَّهِ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏وَجَدَ ‏ ‏عُمَرُ ‏ ‏فَذَكَرَ مَعْنَاهُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْحَارِثِ ‏ ‏حَدَّثَنِي ‏ ‏حَنْظَلَةُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏وَأَتَاهُ ‏ ‏أُسَامَةُ ‏ ‏وَقَدْ لَبِسَهَا فَنَظَرَ إِلَيْهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ أَنْتَ كَسَوْتَنِي قَالَ ‏ ‏شَقِّقْهَا بَيْنَ نِسَائِكَ ‏ ‏خُمُرًا ‏ ‏أَوْ اقْضِ بِهَا حَاجَتَكَ ‏","","",""],[4738,4738,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ سُلَيْمَانَ ‏ ‏سَمِعْتُ ‏ ‏حَنْظَلَةَ ‏ ‏سَمِعْتُ ‏ ‏سَالِمًا ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُشِيرُ إِلَى الْمَشْرِقِ ‏ ‏أَوْ قَالَ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُشِيرُ إِلَى الْمَشْرِقِ ‏ ‏وَيَقُولُ ‏ ‏إِنَّ ‏ ‏الْفِتْنَةَ هَاهُنَا هَا إِنَّ الْفِتْنَةَ هَاهُنَا هَا إِنَّ الْفِتْنَةَ هَاهُنَا مِنْ حَيْثُ يُطْلِعُ الشَّيْطَانُ قَرْنَيْهِ ‏","","",""],[4739,4739,"","","‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ سَعْدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ سَلَّامٍ ‏ ‏سَمِعْتُ ‏ ‏يَحْيَى بْنَ أَبِي كَثِيرٍ ‏ ‏يُخْبِرُ أَنَّ ‏ ‏أَبَا سَلَمَةَ ‏ ‏أَخْبَرَهُ عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّهُ سَمِعَهُ يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏الشَّهْرُ تِسْعٌ وَعِشْرُونَ ‏","","",""],[4740,4740,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ الزُّبَيْرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ سَعْدٍ ‏ ‏قَالَ ‏ ‏كُنْتُ مَعَ ‏ ‏ابْنِ عُمَرَ ‏ ‏فَكَانَ ‏ ‏يُصَلِّي عَلَى ‏ ‏رَاحِلَتِهِ ‏ ‏هَاهُنَا وَهَاهُنَا فَقُلْتُ لَهُ فَقَالَ هَكَذَا رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَفْعَلُ ‏","","",""],[4741,4741,"","","‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ الْحُبَابِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَمَلَ ‏ ‏ثَلَاثًا مِنْ الْحَجَرِ إِلَى الْحَجَرِ وَمَشَى أَرْبَعًا ‏","","",""],[4742,4742,"","","‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ الْحُبَابِ ‏ ‏حَدَّثَنِي ‏ ‏أُسَامَةُ بْنُ زَيْدٍ ‏ ‏حَدَّثَنِي ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمَّا رَجَعَ مِنْ ‏ ‏أُحُدٍ ‏ ‏فَجَعَلَتْ نِسَاءُ ‏ ‏الْأَنْصَارِ ‏ ‏يَبْكِينَ عَلَى مَنْ قُتِلَ مِنْ أَزْوَاجِهِنَّ قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَكِنْ ‏ ‏حَمْزَةُ ‏ ‏لَا ‏ ‏بَوَاكِيَ لَهُ قَالَ ثُمَّ نَامَ فَاسْتَنْبَهَ وَهُنَّ يَبْكِينَ قَالَ فَهُنَّ الْيَوْمَ إِذًا يَبْكِينَ يَنْدُبْنَ ‏ ‏بِحَمْزَةَ ‏","","",""],[4743,4743,"","","‏ ‏حَدَّثَنَا ‏ ‏عَتَّابٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏وَعَلِيُّ بْنُ إِسْحَاقَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏أَخْبَرَنَا ‏ ‏يُونُسُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏حَمْزَةَ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَرَادَ اللَّهُ بِقَوْمٍ عَذَابًا أَصَابَ الْعَذَابُ مَنْ كَانَ فِيهِمْ ثُمَّ بُعِثُوا عَلَى أَعْمَالِهِمْ ‏ ‏وَقَالَ ‏ ‏عَلِيٌّ ‏ ‏فِي حَدِيثِهِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏حَمْزَةُ بْنُ عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُهُ ‏","","",""],[4744,4744,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ بْنُ عَبْدِ الْمَجِيدِ الثَّقَفِيُّ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏مَا أَتَيْتُ عَلَى الرُّكْنِ مُنْذُ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَمْسَحُهُ فِي ‏ ‏شِدَّةٍ ‏ ‏وَلَا رَخَاءٍ إِلَّا مَسَحْتُهُ ‏","","",""],[4745,4745,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْأَعْلَى بْنُ عَبْدِ الْأَعْلَى ‏ ‏عَنْ ‏ ‏خَالِدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَقِيقٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏صَلَاةُ اللَّيْلِ مَثْنَى مَثْنَى فَإِذَا خَشِيتَ الْفَجْرَ ‏ ‏فَأَوْتِرْ ‏ ‏بِوَاحِدَةٍ ‏","","",""],[4746,4746,"","","‏ ‏حَدَّثَنَا ‏ ‏الضَّحَّاكُ بْنُ مَخْلَدٍ أَبُو عَاصِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏حَدِيثِ ‏ ‏سَالِمِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ النَّاسَ فِي عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُضْرَبُونَ إِذَا ابْتَاعُوا الطَّعَامَ ‏ ‏جُزَافًا ‏ ‏أَنْ يَبِيعُوهُ حَتَّى ‏ ‏يُؤْوُوهُ ‏ ‏إِلَى رِحَالِهِمْ ‏","","",""],[4747,4747,"","","‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ خَالِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي ذِئْبٍ ‏ ‏وَيَزِيدُ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏الْحَارِثِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏إِنْ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيَأْمُرُنَا بِالتَّخْفِيفِ وَإِنْ كَانَ لَيَؤُمُّنَا ‏ ‏بِالصَّافَّاتِ ‏ ‏قَالَ ‏ ‏يَزِيدُ ‏ ‏فِي الصُّبْحِ ‏","","",""],[4748,4748,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ يَعْنِي الْحَدَّادَ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي الصِّدِّيقِ النَّاجِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا وَضَعْتُمْ مَوْتَاكُمْ فِي الْقُبُورِ فَقُولُوا بِسْمِ اللَّهِ وَعَلَى مِلَّةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[4749,4749,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ يَحْيَى ‏ ‏أَنَّ ‏ ‏عَمَّهُ ‏ ‏وَاسِعَ بْنَ حَبَّانَ ‏ ‏أَخْبَرَهُ أَنَّهُ سَمِعَ ‏ ‏ابْنَ عُمَرَ ‏ ‏قَالَ ‏ ‏لَقَدْ ظَهَرْتُ ذَاتَ يَوْمٍ عَلَى ظَهْرِ بَيْتِنَا فَرَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَاعِدًا عَلَى ‏ ‏لَبِنَتَيْنِ ‏ ‏مُسْتَقْبِلًا ‏ ‏بَيْتَ الْمَقْدِسِ ‏","","",""],[4750,4750,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏صَلَاةُ الْمَغْرِبِ ‏ ‏وِتْرُ ‏ ‏النَّهَارِ ‏ ‏فَأَوْتِرُوا ‏ ‏صَلَاةَ اللَّيْلِ ‏","","",""],[4751,4751,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏عَنْ ‏ ‏حَجَّاجٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ الْمُغِيرَةِ الطَّائِفِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْمِقْدَامِ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَمْشِي بَيْنَ ‏ ‏الصَّفَا ‏ ‏وَالْمَرْوَةِ ‏ ‏فَقُلْتُ لَهُ ‏ ‏أَبَا عَبْدِ الرَّحْمَنِ ‏ ‏مَا لَكَ لَا ‏ ‏تَرْمُلُ ‏ ‏فَقَالَ قَدْ ‏ ‏رَمَلَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَتَرَكَ ‏","","",""],[4752,4752,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏حُسَيْنُ بْنُ ذَكْوَانَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏حَدَّثَنِي ‏ ‏سُلَيْمَانُ ‏ ‏مَوْلَى ‏ ‏مَيْمُونَةَ ‏ ‏سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا تُصَلُّوا صَلَاةً فِي يَوْمٍ مَرَّتَيْنِ ‏","","",""],[4753,4753,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ الْخَالِقِ بْنُ سَلَمَةَ الشَّيْبَانِيُّ ‏ ‏سَمِعْتُ ‏ ‏سَعِيدَ بْنَ الْمُسَيَّبِ ‏ ‏سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏كُنْتُ عِنْدَ مِنْبَرِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُدُومَ ‏ ‏وَفْدِ عَبْدِ الْقَيْسِ ‏ ‏مَعَ ‏ ‏الْأَشَجِّ ‏ ‏فَسَأَلُوا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الْأَشْرِبَةِ ‏ ‏فَنَهَاهُمْ عَنْ ‏ ‏الْحَنْتَمِ ‏ ‏وَالدُّبَّاءِ ‏ ‏وَالنَّقِيرِ ‏","","",""],[4754,4754,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏بَكْرٍ ‏ ‏قَالَ ذَكَرْتُ ‏ ‏لِابْنِ عُمَرَ ‏ ‏أَنَّ ‏ ‏أَنَسًا ‏ ‏حَدَّثَنَا أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَهَلَّ ‏ ‏بِعُمْرَةٍ وَحَجٍّ فَقَالَ ‏ ‏وَهِلَ ‏ ‏أَنَسٌ ‏ ‏إِنَّمَا ‏ ‏أَهَلَّ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالْحَجِّ وَأَهْلَلْنَا مَعَهُ فَلَمَّا قَدِمَ قَالَ مَنْ لَمْ يَكُنْ مَعَهُ ‏ ‏هَدْيٌ ‏ ‏فَلْيَجْعَلْهَا عُمْرَةً وَكَانَ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَدْيٌ ‏ ‏فَلَمْ ‏ ‏يَحِلَّ ‏","","",""],[4755,4755,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏أَرْبَعًا تَلَقَّفْتُهُنَّ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ لَبَّيْكَ لَا شَرِيكَ لَكَ لَبَّيْكَ إِنَّ الْحَمْدَ وَالنِّعْمَةَ لَكَ وَالْمُلْكَ لَا شَرِيكَ لَكَ ‏","","",""],[4756,4756,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏عَنْ ‏ ‏عَطِيَّةَ الْعَوْفِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ تُبَاعَ الثَّمَرَةُ حَتَّى يَبْدُوَ صَلَاحُهَا قَالَ قَالُوا يَا رَسُولَ اللَّهِ مَا صَلَاحُهَا قَالَ إِذَا ذَهَبَتْ ‏ ‏عَاهَتُهَا ‏ ‏وَخَلَصَ ‏ ‏طَيِّبُهَا ‏","","",""],[4757,4757,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَسْهَمَ ‏ ‏لِلرَّجُلِ وَفَرَسِهِ ثَلَاثَةَ ‏ ‏أَسْهُمٍ ‏ ‏سَهْمًا ‏ ‏لَهُ ‏ ‏وَسَهْمَيْنِ ‏ ‏لِفَرَسِهِ ‏","","",""],[4758,4758,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي لَأَعْرِفُ شَجَرَةً بَرَكَتُهَا كَالرَّجُلِ الْمُسْلِمِ النَّخْلَةُ ‏","","",""],[4759,4759,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ إِدْرِيسَ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ يَعْنِي ابْنَ أَبِي سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏يُصَلِّي حَيْثُمَا تَوَجَّهَتْ بِهِ رَاحِلَتُهُ وَقَدْ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَفْعَلُ ذَلِكَ وَيَتَأَوَّلُ عَلَيْهِ ‏ { ‏وَحَيْثُ مَا كُنْتُمْ ‏ ‏فَوَلُّوا ‏ ‏وُجُوهَكُمْ ‏}","","",""],[4760,4760,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏أَخَذَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِثَوْبِي ‏ ‏أَوْ بِبَعْضِ جَسَدِي ‏ ‏وَقَالَ ‏ ‏عَبْدَ اللَّهِ ‏ ‏كُنْ كَأَنَّكَ غَرِيبٌ أَوْ عَابِرُ سَبِيلٍ وَعُدَّ نَفْسَكَ مِنْ أَهْلِ الْقُبُورِ ‏","","",""],[4761,4761,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَلْبَسُ الْمُحْرِمُ الْبُرْنُسَ وَلَا الْقَمِيصَ وَلَا الْعِمَامَةَ وَلَا السَّرَاوِيلَ وَلَا الْخُفَّيْنِ إِلَّا أَنْ يَضْطَرَّ يَقْطَعُهُ مِنْ عِنْدِ الْكَعْبَيْنِ وَلَا يَلْبَسُ ثَوْبًا مَسَّهُ ‏ ‏الْوَرْسُ ‏ ‏وَلَا ‏ ‏الزَّعْفَرَانُ ‏ ‏إِلَّا أَنْ يَكُونَ غَسِيلًا ‏","","",""],[4762,4762,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏مَالِكٍ يَعْنِي ابْنَ مِغْوَلٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سُئِلَ عَنْ الضَّبِّ فَقَالَ لَا آكُلُهُ وَلَا ‏ ‏أَنْهَى عَنْهُ ‏","","",""],[4763,4763,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏مَالِكٍ يَعْنِي ابْنَ مِغْوَلٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَتَى الْجُمُعَةَ فَلْيَغْتَسِلْ ‏","","",""],[4764,4764,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ الْمُغِيرَةِ الطَّائِفِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مِقْدَامِ بْنِ وَرْدٍ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏طَافَ بَيْنَ ‏ ‏الصَّفَا ‏ ‏وَالْمَرْوَةِ ‏ ‏فَلَمْ ‏ ‏يَرْمُلْ ‏ ‏فَقُلْتُ لِمَ تَفْعَلُ هَذَا قَالَ فَقَالَ نَعَمْ كُلًّا قَدْ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَعَلَ ‏ ‏رَمَلَ ‏ ‏وَتَرَكَ ‏","","",""],[4765,4765,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ عَبْدِ الْمَلِكِ بْنِ أَبِي غَنِيَّةَ ‏ ‏أَنْبَأَنَا ‏ ‏أَبُو جَنَابٍ ‏ ‏عَنْ ‏ ‏شَهْرِ بْنِ حَوْشَبٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَئِنْ تَرَكْتُمْ الْجِهَادَ وَأَخَذْتُمْ بِأَذْنَابِ الْبَقَرِ وَتَبَايَعْتُمْ ‏ ‏بِالْعِينَةِ ‏ ‏لَيُلْزِمَنَّكُمْ اللَّهُ مَذَلَّةً فِي رِقَابِكُمْ لَا تَنْفَكُّ عَنْكُمْ حَتَّى تَتُوبُوا إِلَى اللَّهِ وَتَرْجِعُوا عَلَى مَا كُنْتُمْ عَلَيْهِ ‏","","",""],[4766,4766,"","","‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ عُبَيْدٍ الطَّنَافِسِيُّ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ يَعْنِي السُّبَيْعِيَّ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى الْمِنْبَرِ يَقُولُ ‏ ‏مَنْ أَتَى الْجُمُعَةَ فَلْيَغْتَسِلْ ‏","","",""],[4767,4767,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ الْمَلِكِ ‏ ‏سَمِعْتُ ‏ ‏سَعِيدَ بْنَ جُبَيْرٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏فَقُلْتُ يَا ‏ ‏أَبَا عَبْدِ الرَّحْمَنِ ‏ ‏الْمُتَلَاعِنَيْنِ ‏ ‏يُفَرَّقُ بَيْنَهُمَا قَالَ سُبْحَانَ اللَّهِ نَعَمْ إِنَّ أَوَّلَ مَنْ سَأَلَ عَنْ ذَلِكَ فُلَانٌ قَالَ يَا رَسُولَ اللَّهِ أَرَأَيْتَ لَوْ أَنَّ أَحَدَنَا رَأَى امْرَأَتَهُ عَلَى ‏ ‏فَاحِشَةٍ ‏ ‏كَيْفَ يَصْنَعُ إِنْ سَكَتَ سَكَتَ عَلَى أَمْرٍ عَظِيمٍ وَإِنْ تَكَلَّمَ فَمِثْلُ ذَلِكَ فَسَكَتَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَمْ يُجِبْهُ فَقَامَ ‏ ‏لِحَاجَتِهِ ‏ ‏فَلَمَّا كَانَ بَعْدَ ذَلِكَ أَتَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ إِنَّ الَّذِي سَأَلْتُكَ عَنْهُ قَدْ ابْتُلِيتُ بِهِ قَالَ فَأَنْزَلَ اللَّهُ تَعَالَى هَذِهِ الْآيَاتِ فِي سُورَةِ ‏ ‏النُّورِ ‏ { ‏وَالَّذِينَ يَرْمُونَ أَزْوَاجَهُمْ ‏} ‏حَتَّى خَتَمَ الْآيَاتِ فَدَعَا الرَّجُلَ فَتَلَاهُنَّ عَلَيْهِ وَذَكَّرَهُ بِاللَّهِ تَعَالَى وَأَخْبَرَهُ أَنَّ عَذَابَ الدُّنْيَا أَهْوَنُ مِنْ عَذَابِ الْآخِرَةِ فَقَالَ وَالَّذِي بَعَثَكَ بِالْحَقِّ مَا كَذَبْتُ عَلَيْهَا ثُمَّ دَعَا الْمَرْأَةَ فَوَعَظَهَا وَذَكَّرَهَا وَأَخْبَرَهَا بِأَنَّ عَذَابَ الدُّنْيَا أَهْوَنُ مِنْ عَذَابِ الْآخِرَةِ فَقَالَتْ وَالَّذِي بَعَثَكَ بِالْحَقِّ إِنَّهُ لَكَاذِبٌ فَدَعَا الرَّجُلَ فَشَهِدَ أَرْبَعَ شَهَادَاتٍ بِاللَّهِ إِنَّهُ لَمِنْ الصَّادِقِينَ وَالْخَامِسَةَ أَنَّ لَعْنَةَ اللَّهِ عَلَيْهِ إِنْ كَانَ مِنْ الْكَاذِبِينَ ثُمَّ دَعَا بِالْمَرْأَةِ فَشَهِدَتْ أَرْبَعَ شَهَادَاتٍ بِاللَّهِ إِنَّهُ لَمِنْ الْكَاذِبِينَ وَالْخَامِسَةَ أَنَّ غَضَبَ اللَّهِ عَلَيْهَا إِنْ كَانَ مِنْ الصَّادِقِينَ ثُمَّ فَرَّقَ بَيْنَهُمَا ‏","","",""],[4768,4768,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏مُسْلِمٍ الْخَبَّاطِ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ ‏ ‏يُتَلَقَّى الرُّكْبَانُ ‏ ‏أَوْ يَبِيعَ حَاضِرٌ ‏ ‏لِبَادٍ ‏ ‏وَلَا يَخْطُبْ أَحَدُكُمْ عَلَى خِطْبَةِ أَخِيهِ حَتَّى يَنْكِحَ أَوْ يَدَعَ وَلَا صَلَاةَ بَعْدَ الْعَصْرِ حَتَّى تَغِيبَ الشَّمْسُ وَلَا بَعْدَ الصُّبْحِ حَتَّى تَرْتَفِعَ الشَّمْسُ أَوْ تُضْحِيَ ‏","","",""],[4769,4769,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏الْحَارِثِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏حَمْزَةَ بْنِ عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏كَانَتْ تَحْتِي امْرَأَةٌ أُحِبُّهَا وَكَانَ ‏ ‏عُمَرُ ‏ ‏يَكْرَهُهَا فَأَمَرَنِي أَنْ أُطَلِّقَهَا فَأَبَيْتُ فَأَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ إِنَّ عِنْدَ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏امْرَأَةً كَرِهْتُهَا لَهُ فَأَمَرْتُهُ أَنْ يُطَلِّقَهَا فَأَبَى فَقَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏عَبْدَ اللَّهِ ‏ ‏طَلِّقْ امْرَأَتَكَ فَطَلَّقْتُهَا ‏","","",""],[4770,4770,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ عَبْدِ اللَّهِ بْنِ سُرَاقَةَ ‏ ‏قَالَ ‏ ‏كُنَّا فِي سَفَرٍ وَمَعَنَا ‏ ‏ابْنُ عُمَرَ ‏ ‏فَسَأَلْتُهُ فَقَالَ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يُسَبِّحُ فِي السَّفَرِ قَبْلَ الصَّلَاةِ وَلَا بَعْدَهَا قَالَ وَسَأَلْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏عَنْ بَيْعِ الثِّمَارِ فَقَالَ نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ بَيْعِ الثِّمَارِ حَتَّى تَذْهَبَ ‏ ‏الْعَاهَةُ ‏ ‏قُلْتُ ‏ ‏أَبَا عَبْدِ الرَّحْمَنِ ‏ ‏وَمَا تَذْهَبُ ‏ ‏الْعَاهَةُ ‏ ‏مَا ‏ ‏الْعَاهَةُ ‏ ‏قَالَ ‏ ‏طُلُوعُ ‏ ‏الثُّرَيَّا ‏","","",""],[4771,4771,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَبَهْزٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏جَبَلَةَ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يُحَدِّثُ قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْحَنْتَمَةِ ‏ ‏قُلْتُ لَهُ مَا ‏ ‏الْحَنْتَمَةُ ‏ ‏قَالَ ‏ ‏الْجَرَّةُ ‏","","",""],[4772,4772,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏سَمِعْتُ ‏ ‏مُحَارِبَ بْنَ دِثَارٍ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ ‏ ‏جَرَّ ‏ ‏ثَوْبَهُ مِنْ ‏ ‏مَخِيلَةٍ ‏ ‏لَمْ يَنْظُرْ اللَّهُ إِلَيْهِ يَوْمَ الْقِيَامَةِ ‏","","",""],[4773,4773,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَالْحَجَّاجُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَارِبِ بْنِ دِثَارٍ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الدُّبَّاءِ ‏ ‏وَالْحَنْتَمِ ‏ ‏وَالْمُزَفَّتِ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏سَمِعْتُهُ غَيْرَ مَرَّةٍ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏وَقَالَ أَشُكُّ فِي ‏ ‏النَّقِيرِ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏فِي حَدِيثِهِ مَرَّاتٍ ‏","","",""],[4774,4774,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي التَّيَّاحِ ‏ ‏عَنْ ‏ ‏أَبِي مِجْلَزٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْوَتْرُ ‏ ‏آخِرُ رَكْعَةٍ مِنْ اللَّيْلِ ‏","","",""],[4775,4775,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ بْنِ قَيْسٍ ‏ ‏سَمِعْتُ ‏ ‏سَعِيدَ بْنَ عَمْرِو بْنِ سَعِيدٍ ‏ ‏يُحَدِّثُ أَنَّهُ سَمِعَ ‏ ‏ابْنَ عُمَرَ ‏ ‏يُحَدِّثُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِنَّا أُمَّةٌ أُمِّيَّةٌ لَا نَكْتُبُ وَلَا نَحْسُبُ الشَّهْرُ هَكَذَا وَهَكَذَا وَهَكَذَا وَعَقَدَ الْإِبْهَامَ فِي الثَّالِثَةِ وَالشَّهْرُ هَكَذَا وَهَكَذَا وَهَكَذَا ‏ ‏يَعْنِي تَمَامَ ثَلَاثِينَ ‏","","",""],[4776,4776,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْمِنْهَالِ بْنِ عَمْرٍو ‏ ‏وَسَمِعْتُ ‏ ‏سَعِيدَ بْنَ جُبَيْرٍ ‏ ‏قَالَ ‏ ‏مَرَرْتُ مَعَ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَلَى طَرِيقٍ مِنْ طُرُقِ ‏ ‏الْمَدِينَةِ ‏ ‏فَإِذَا فِتْيَةٌ قَدْ نَصَبُوا دَجَاجَةً يَرْمُونَهَا لَهُمْ كُلُّ خَاطِئَةٍ قَالَ فَغَضِبَ وَقَالَ مَنْ فَعَلَ هَذَا قَالَ فَتَفَرَّقُوا فَقَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏لَعَنَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ ‏ ‏يُمَثِّلُ ‏ ‏بِالْحَيَوَانِ ‏","","",""],[4777,4777,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏زَيْدٍ ‏ ‏وَأَبِي بَكْرٍ ‏ ‏ابْنَيْ ‏ ‏مُحَمَّدٍ ‏ ‏أَنَّهُمَا سَمِعَا ‏ ‏نَافِعًا ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ كَانَ يَقُولُ ‏ ‏لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ لَبَّيْكَ لَا شَرِيكَ لَكَ لَبَّيْكَ إِنَّ الْحَمْدَ وَالنِّعْمَةَ لَكَ وَالْمُلْكَ لَا شَرِيكَ لَكَ ‏","","",""],[4778,4778,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏وَاقِدِ بْنِ مُحَمَّدِ بْنِ زَيْدٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏نَافِعًا ‏ ‏قَالَ ‏ ‏رَأَى ‏ ‏ابْنُ عُمَرَ ‏ ‏مِسْكِينًا فَجَعَلَ ‏ ‏يُدْنِيهِ ‏ ‏وَيَضَعُ بَيْنَ يَدَيْهِ فَجَعَلَ يَأْكُلُ أَكْلًا كَثِيرًا فَقَالَ لِي لَا تُدْخِلَنَّ هَذَا عَلَيَّ فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ الْكَافِرَ يَأْكُلُ فِي سَبْعَةِ أَمْعَاءٍ ‏","","",""],[4779,4779,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَا تَمْنَعُوا نِسَاءَكُمْ الْمَسَاجِدَ بِاللَّيْلِ ‏ ‏فَقَالَ ‏ ‏سَالِمٌ ‏ ‏أَوْ بَعْضُ بَنِيهِ ‏ ‏وَاللَّهِ لَا نَدَعُهُنَّ يَتَّخِذْنَهُ ‏ ‏دَغَلًا ‏ ‏قَالَ فَلَطَمَ صَدْرَهُ وَقَالَ ‏ ‏أُحَدِّثُكَ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَتَقُولُ هَذَا ‏","","",""],[4780,4780,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏سَمِعْتُ ‏ ‏سُلَيْمَانَ الْأَعْمَشَ ‏ ‏وَقَالَ ‏ ‏حَجَّاجٌ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏يَحْيَى بْنِ وَثَّابٍ ‏ ‏عَنْ ‏ ‏شَيْخٍ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏وَأُرَاهُ ‏ ‏ابْنَ عُمَرَ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏سُلَيْمَانُ ‏ ‏وَهُوَ ‏ ‏ابْنُ عُمَرَ ‏ ‏يُحَدِّثُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏الْمُؤْمِنُ الَّذِي يُخَالِطُ النَّاسَ وَيَصْبِرُ عَلَى أَذَاهُمْ أَعْظَمُ أَجْرًا مِنْ الَّذِي لَا يُخَالِطُهُمْ وَلَا يَصْبِرُ عَلَى أَذَاهُمْ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏خَيْرٌ مِنْ الَّذِي لَا يُخَالِطُهُمْ ‏","","",""],[4781,4781,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏ذَكْوَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا كُنْتُمْ ثَلَاثَةً فَلَا يَتَنَاجَ اثْنَانِ دُونَ وَاحِدٍ ‏ ‏قَالَ ‏ ‏فَقُلْتُ ‏ ‏لِابْنِ عُمَرَ ‏ ‏فَإِذَا كَانُوا أَرْبَعَةً قَالَ ‏ ‏فَلَا بَأْسَ بِهِ ‏","","",""],[4782,4782,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏بَكْرِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّهُ قَالَ ‏ ‏تَلْبِيَةُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ لَبَّيْكَ لَا شَرِيكَ لَكَ لَبَّيْكَ إِنَّ الْحَمْدَ وَالنِّعْمَةَ لَكَ وَالْمُلْكَ لَا شَرِيكَ لَكَ ‏","","",""],[4783,4783,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَعَبْدُ اللَّهِ بْنُ بَكْرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏يُونُسَ بْنِ جُبَيْرٍ ‏ ‏أَنَّهُ ‏ ‏سَأَلَ ‏ ‏ابْنَ عُمَرَ ‏ ‏عَنْ رَجُلٍ طَلَّقَ امْرَأَتَهُ وَهِيَ حَائِضٌ فَقَالَ أَتَعْرِفُ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏فَإِنَّهُ طَلَّقَ امْرَأَتَهُ حَائِضًا فَانْطَلَقَ ‏ ‏عُمَرُ ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَخْبَرَهُ بِذَلِكَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُرْهُ فَلْيُرَاجِعْهَا ثُمَّ إِنْ بَدَا لَهُ طَلَاقُهَا طَلَّقَهَا فِي قُبُلِ عِدَّتِهَا ‏ ‏قَالَ ‏ ‏ابْنُ بَكْرٍ ‏ ‏أَوْ فِي قُبُلِ طُهْرِهَا ‏ ‏فَقُلْتُ ‏ ‏لِابْنِ عُمَرَ ‏ ‏أَيُحْسَبُ طَلَاقُهُ ذَلِكَ طَلَاقًا قَالَ ‏ ‏نَعَمْ أَرَأَيْتَ إِنْ عَجَزَ وَاسْتَحْمَقَ ‏","","",""],[4784,4784,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏يَعْلَى بْنِ حَكِيمٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا آكُلُهُ وَلَا آمُرُ بِهِ وَلَا أَنْهَى عَنْهُ ‏","","",""],[4785,4785,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ شِهَابٍ ‏ ‏وَعَبْدُ الْأَعْلَى ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏أَسْلَمَ ‏ ‏غَيْلَانُ بْنُ سَلَمَةَ ‏ ‏وَتَحْتَهُ عَشْرُ نِسْوَةٍ فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خُذْ مِنْهُنَّ أَرْبَعًا ‏","","",""],[4786,4786,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏أَخْبَرَنَا ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَتْرُكُوا النَّارَ فِي بُيُوتِكُمْ حِينَ تَنَامُونَ ‏","","",""],[4787,4787,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏أَخْبَرَنَا ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّمَا النَّاسُ كَإِبِلِ الْمِائَةِ لَا يُوجَدُ فِيهَا ‏ ‏رَاحِلَةٌ ‏","","",""],[4788,4788,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏وَمُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُقْبَةُ بْنُ حُرَيْثٍ ‏ ‏سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْجَرِّ ‏ ‏وَهِيَ ‏ ‏الدُّبَّاءُ ‏ ‏وَالْمُزَفَّتُ ‏ ‏وَقَالَ ‏ ‏انْتَبِذُوا ‏ ‏فِي ‏ ‏الْأَسْقِيَةِ ‏","","",""],[4789,4789,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏عُقْبَةُ بْنُ حُرَيْثٍ ‏ ‏سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ كَانَ مُلْتَمِسًا فَلْيَلْتَمِسْهَا فِي الْعَشْرِ فَإِنْ عَجَزَ أَوْ ضَعُفَ فَلَا يُغْلَبْ عَلَى السَّبْعِ الْبَوَاقِي ‏","","",""],[4790,4790,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏أَخْبَرَنِي ‏ ‏عُقْبَةُ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَاةُ اللَّيْلِ مَثْنَى مَثْنَى فَإِنْ خَشِيتَ الصُّبْحَ فَأَوْتِرْ بِرَكْعَةٍ ‏ ‏قَالَ ‏ ‏قُلْتُ مَا مَثْنَى مَثْنَى قَالَ ‏ ‏رَكْعَتَانِ رَكْعَتَانِ ‏","","",""],[4791,4791,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏طَاوُسًا ‏ ‏حِينَ يَفْتَتِحُ الصَّلَاةَ يَرْفَعُ يَدَيْهِ وَحِينَ يَرْكَعُ وَحِينَ يَرْفَعُ رَأْسَهُ مِنْ الرُّكُوعِ ‏ ‏فَحَدَّثَنِي ‏ ‏رَجُلٌ ‏ ‏مِنْ أَصْحَابِهِ ‏ ‏أَنَّهُ يُحَدِّثُهُ عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَدَّثَنَاه ‏ ‏أَبُو النَّضْرِ ‏ ‏بِمَعْنَاهُ ‏","","",""],[4792,4792,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يُحَدِّثُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِذَا قَالَ الرَّجُلُ لِلرَّجُلِ يَا كَافِرُ فَقَدْ ‏ ‏بَاءَ ‏ ‏بِهِ أَحَدُهُمَا إِنْ كَانَ كَمَا قَالَ وَإِلَّا رَجَعَتْ عَلَى الْآخَرِ ‏","","",""],[4793,4793,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏رَجُلٌ ‏ ‏مِنْ ‏ ‏قُرَيْشٍ ‏ ‏يُغْبَنُ ‏ ‏فِي الْبَيْعِ فَذَكَرَ ذَلِكَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ لَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُلْ ‏ ‏لَا ‏ ‏خِلَابَةَ ‏","","",""],[4794,4794,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏الْمَعْنَى ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏عَنْ ‏ ‏جَبَلَةَ ‏ ‏وَقَالَ ‏ ‏ابْنُ جَعْفَرٍ ‏ ‏سَمِعْتُ ‏ ‏جَبَلَةَ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏ابْنُ الزُّبَيْرِ ‏ ‏يَرْزُقُنَا التَّمْرَ قَالَ وَقَدْ كَانَ أَصَابَ النَّاسَ يَوْمَئِذٍ جَهْدٌ فَكُنَّا نَأْكُلُ فَيَمُرُّ عَلَيْنَا ‏ ‏ابْنُ عُمَرَ ‏ ‏وَنَحْنُ نَأْكُلُ فَيَقُولُ لَا ‏ ‏تُقَارِنُوا ‏ ‏فَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏الْإِقْرَانِ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏نَهَى عَنْ ‏ ‏الْقِرَانِ ‏ ‏إِلَّا أَنْ يَسْتَأْذِنَ الرَّجُلُ أَخَاهُ ‏ ‏وَقَالَ ‏ ‏شُعْبَةُ ‏ ‏لَا أُرَى هَذِهِ الْكَلِمَةَ فِي ‏ ‏الِاسْتِئْذَانِ إِلَّا مِنْ كَلَامِ ‏ ‏ابْنِ عُمَرَ ‏","","",""],[4795,4795,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏وَمُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏جَبَلَةَ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يُحَدِّثُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَنْ جَرَّ ثَوْبًا مِنْ ثِيَابِهِ مِنْ ‏ ‏مَخِيلَةٍ ‏ ‏فَإِنَّ اللَّهَ تَعَالَى لَا يَنْظُرُ إِلَيْهِ يَوْمَ الْقِيَامَةِ ‏","","",""],[4796,4796,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَبَهْزٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏جَبَلَةَ بْنِ سُحَيْمٍ ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏أَخْبَرَنِي ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الشَّهْرُ هَكَذَا وَطَبَّقَ بِأَصَابِعِهِ مَرَّتَيْنِ وَكَسَرَ فِي الثَّالِثَةِ الْإِبْهَامَ ‏ ‏قَالَ ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏فِي حَدِيثِهِ ‏ ‏يَعْنِي قَوْلَهُ تِسْعٌ وَعِشْرِينَ ‏","","",""],[4797,4797,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏خُبَيْبِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏حَفْصِ بْنِ عَاصِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّهُ كَانَ ‏ ‏يُصَلِّي حَيْثُ تَوَجَّهَتْ بِهِ رَاحِلَتُهُ قَالَ وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَفْعَلُهُ ‏","","",""],[4798,4798,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏خُبَيْبٍ يَعْنِي ابْنَ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏حَفْصِ بْنِ عَاصِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏خَرَجْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَكَانَ ‏ ‏يُصَلِّي صَلَاةَ ‏ ‏السَّفَرِ ‏ ‏يَعْنِي رَكْعَتَيْنِ ‏ ‏وَمَعَ ‏ ‏أَبِي بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏وَعُثْمَانَ ‏ ‏سِتَّ سِنِينَ مِنْ إِمْرَتِهِ ثُمَّ صَلَّى أَرْبَعًا ‏","","",""],[4799,4799,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي فَرْوَةَ الْهَمْدَانِيِّ ‏ ‏سَمِعْتُ ‏ ‏عَوْنًا الْأَزْدِيَّ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏عُمَرُ بْنُ عُبَيْدِ اللَّهِ بْنِ مَعْمَرٍ ‏ ‏أَمِيرًا عَلَى ‏ ‏فَارِسَ ‏ ‏فَكَتَبَ إِلَى ‏ ‏ابْنِ عُمَرَ ‏ ‏يَسْأَلُهُ عَنْ الصَّلَاةِ فَكَتَبَ ‏ ‏ابْنُ عُمَرَ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا خَرَجَ مِنْ أَهْلِهِ صَلَّى رَكْعَتَيْنِ حَتَّى يَرْجِعَ إِلَيْهِمْ ‏","","",""],[4800,4800,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَحَجَّاجٌ ‏ ‏الْمَعْنَى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏مُسْلِمُ بْنُ أَبِي مَرْيَمَ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏مِنْ ‏ ‏بَنِي أُمَيَّةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ عَلِيٍّ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏الْأُمَوِيَّ ‏ ‏قَالَ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏وَرَأَى رَجُلًا يَعْبَثُ فِي صَلَاتِهِ فَقَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏لَا تَعْبَثْ فِي صَلَاتِكَ وَاصْنَعْ كَمَا كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَصْنَعُ ‏ ‏قَالَ ‏ ‏مُحَمَّدٌ ‏ ‏فَوَضَعَ ‏ ‏ابْنُ عُمَرَ ‏ ‏فَخِذَهُ الْيُمْنَى عَلَى الْيُسْرَى وَيَدَهُ الْيُسْرَى عَلَى رُكْبَتِهِ الْيُسْرَى وَوَضَعَ يَدَهُ الْيُمْنَى عَلَى الْيُمْنَى وَقَالَ بِإِصْبَعِهِ ‏","","",""]];
